/* Question bank PA test (English convenience translation), Wft Income. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["inkomen"] = [
["For how long must an employer, as a general rule, continue to pay the wages of a sick employee?", [["A maximum of 104 weeks", "As a general rule, the obligation to continue paying wages during sickness lasts two years (104 weeks); a WIA benefit may follow after that."], ["A maximum of 52 weeks (one year)", "After 52 weeks the continued payment of wages still goes on; the first-year evaluation takes place during that period."], ["A maximum of 26 weeks", "Six months is far too short; the employer bears the risk for two years."], ["A maximum of 156 weeks (three years)", "Three years applies only in the case of a wage sanction or a voluntary extension, not as the general rule."]], "1b.1"],
["What is the minimum percentage of wages an employer must continue to pay during sickness under the Dutch Civil Code (BW)?", [["70% of wages, with at least the minimum wage in the first year", "This is the statutory minimum; the 70% applies up to a maximum, and in the first year of sickness the employee may not end up below the minimum wage."], ["100% of wages for the entire two-year period", "Full continued payment occurs under a collective labour agreement or employment contract, but it is not a statutory obligation."], ["75% of wages in the first two months and 70% thereafter", "This build-up belongs to the WW (unemployment benefit) and the wage-related WGA benefit, not to continued payment of wages during sickness."], ["70% of the minimum wage, regardless of the wage earned", "Continued payment of wages is linked to the employee's own wage, not to a percentage of the minimum wage."]], "1i.8"],
["Within what period must the problem analysis by the company doctor or occupational health service be completed under the Gatekeeper Improvement Act (Wet verbetering poortwachter)?", [["Within six weeks of the sickness report", "The problem analysis must be drawn up no later than in the sixth week of sickness, so that reintegration can start in good time."], ["Within two weeks of the sickness report", "It does not have to be that fast; the statutory period for the problem analysis is six weeks."], ["Within eight weeks of the sickness report", "Eight weeks is the period for the plan of action, which follows the problem analysis."], ["Within 42 weeks of the sickness report", "In week 42 the sickness is reported to the UWV (Employee Insurance Agency); by then the problem analysis was completed long ago."]], "1i.9"],
["What must the employer and employee draw up together no later than in the eighth week of sickness?", [["A plan of action for reintegration", "Based on the problem analysis, the employer and employee set out in the plan of action which steps will be taken to return to work."], ["A reintegration report for the UWV", "The reintegration report belongs to the WIA application at the end of the waiting period, not to week eight."], ["A first-year evaluation", "The first-year evaluation takes place around the end of the first year of sickness."], ["A settlement agreement", "A settlement agreement arranges the termination of employment and is not a reintegration instrument."]], "1i.9"],
["By when at the latest must an employer report a long-term sick employee as sick to the UWV?", [["In the 42nd week of sickness", "An employee who is still sick must be reported to the UWV no later than in week 42; this is the so-called 42nd-week report."], ["On the first day of sickness", "On the first day of sickness the employee reports sick to the employer; a report to the UWV is not yet necessary at that point."], ["In the sixth week of sickness", "In week six the problem analysis must be completed; the report to the UWV follows later."], ["In the 104th week of sickness", "The waiting period ends in week 104; the WIA application must have been made well before then."]], "1i.9"],
["Sanne (41) is an administrative employee at a wholesaler and earns €3,100 gross per month. She is married and has two school-age children. After a herniated disc she has been sick for almost two years and applies for a WIA benefit. The reintegration report shows that her employer never took up the second track, and the UWV considers the reintegration efforts insufficient. What is the most likely consequence?", [["As a wage sanction, the employer must continue paying wages for up to 52 weeks longer", "If reintegration efforts are insufficient, the UWV can extend the obligation to continue paying wages by up to one year."], ["Sanne receives no WIA benefit and permanently loses her right to a benefit", "The sanction for the employer's failure affects the employer; Sanne's entitlement is only postponed."], ["The employer receives a fine from the AFM", "The AFM supervises the financial markets and is not involved in reintegration."], ["The UWV takes over the continued payment of wages immediately and recovers it from the employer later", "The UWV does not take over the costs; on the contrary, the employer must pay wages for longer."]], "1k.13"],
["What does the 'second track' in reintegration mean?", [["Reintegration with another employer", "If a return to the own employer does not succeed, suitable work outside the company must be sought: the second track."], ["Reintegration in the own job or other work with the own employer", "That is the first track; the own employer is always the first starting point."], ["A second opinion from another company doctor", "A second opinion is a right of the employee, but it is not called the second track."], ["A request for an expert opinion from the UWV", "An expert opinion can help in a disagreement, but it is not a reintegration track."]], "1i.9"],
["Peter (48) is a warehouse employee at a transport company and earns €2,900 gross per month. He lives with a partner and has a twelve-year-old daughter. After a knee operation his employer offers him administrative work, but Peter considers that work unsuitable because of his pain. The employer and employee cannot resolve it between themselves. What can either of them request?", [["An expert opinion from the UWV", "On request, the UWV can give an independent expert opinion on, among other things, suitable work and reintegration efforts."], ["A ruling from Kifid (Dutch Financial Services Complaints Institute)", "Kifid handles complaints about financial services, not employment-law reintegration disputes."], ["A reassessment by the Tax Administration", "The Tax Administration plays no role in assessing suitable work."], ["A binding advice from the absenteeism insurer", "An absenteeism insurer is a party on the employer's side and does not give an independent opinion between employer and employee."]], "1i.9"],
["May an employer dismiss an employee solely because that employee has been sick for more than a year?", [["No, dismissal for sickness is prohibited in the first two years of sickness", "During the first two years of sickness, the employer may in principle not terminate the employment contract because of sickness."], ["Yes, after 52 weeks of sickness the prohibition on termination lapses", "The prohibition on termination is not limited to the first year; in principle it applies for two years."], ["Yes, provided the employer has taken out absenteeism insurance for the wage risk", "Absenteeism insurance covers the employer's financial risk and changes nothing about dismissal law."], ["No, a sick employee can never be dismissed, not even after two years of sickness", "Even in the case of sickness, dismissal may be possible under conditions, for example after two years or for an urgent reason."]], "1i.8"],
["What can be the consequence if a sick employee refuses, without sound reason, to perform suitable work?", [["The employer can stop continuing to pay wages", "An employee who, without good reason, does not cooperate in his reintegration can (temporarily) lose his right to wages."], ["The employee immediately receives a WIA benefit", "Refusing to cooperate does not lead to an earlier benefit, but rather to sanctions."], ["The employer must increase the wages to 100%", "There is no rule requiring the employer to pay more if the employee refuses."], ["The UWV imposes a wage sanction on the employer", "A wage sanction affects the employer who falls short, not the situation in which the employee refuses."]], "1k.5"],
["What is the maximum number of waiting days that may be agreed in the event of sickness, for example in a collective labour agreement?", [["Two waiting days", "By law, a maximum of two waiting days may be agreed for which no wages are paid."], ["Five waiting days", "Five waiting days is not permitted by law; the maximum is lower."], ["Fourteen waiting days", "Fourteen days is a common excess on absenteeism insurance, not a statutory waiting period for employees."], ["None, waiting days are prohibited", "Waiting days are not prohibited; they may be agreed up to the statutory maximum."]], "1b.4"],
["Who is the Sickness Benefits Act (Ziektewet, ZW) primarily intended for?", [["Sick employees who have no (longer an) employer who continues to pay their wages", "The ZW is a safety net, for example for sick WW benefit recipients and flex workers whose contract ends during sickness."], ["All sick employees from the first day of sickness", "Employees with an employer have their wages continued; the ZW is a safety net for specific groups."], ["Self-employed people without disability insurance", "Self-employed people do not fall under the ZW; they must insure themselves privately."], ["Employees who are less than 35% incapacitated for work after two years of sickness", "No ZW benefit exists for this group; they have no right to WIA and are expected to work."]], "1i.2"],
["Kees (29) works as a fitter at an installation company for €2,800 gross per month and lives alone. He has a one-year temporary contract. Three weeks before the end of his contract he breaks his leg in a sports accident, as a result of which he cannot work for months. His employer does not extend the contract. Who provides his income during sickness after the contract ends?", [["The UWV through the Sickness Benefits Act, unless his ex-employer is a ZW own-risk bearer", "After the end of employment, Kees falls into the ZW safety net; if the employer is an own-risk bearer, the ex-employer pays that benefit."], ["His ex-employer through continued payment of wages until the end of the 104 weeks", "When the contract ends, the employer's obligation to continue paying wages also ends."], ["The municipality through the Participation Act", "Social assistance only comes into play if there is no entitlement to an employee insurance benefit or other income."], ["The SVB (Social Insurance Bank) through the Supplementary Benefits Act", "The Supplementary Benefits Act is administered by the UWV and only tops up; it is not a replacement for the ZW."]], "1b.5"],
["What happens in the first-year Sickness Benefits Act assessment (EZWb) of a safety-net employee (vangnetter)?", [["The UWV assesses what he can still earn and whether he thereby loses his ZW entitlement", "After one year of sickness, the safety-net employee is assessed against generally accepted work; anyone who can earn enough loses the ZW benefit."], ["The UWV assesses whether the ex-employer receives a wage sanction for too little reintegration", "A wage sanction belongs to the WIA application of an employee with an employer, not to the EZWb."], ["With an incapacity for work of 80% or more, the UWV automatically awards an IVA benefit", "An IVA benefit requires a WIA assessment after the waiting period; the EZWb is not part of that."], ["The company doctor draws up a plan of action", "The plan of action belongs to the start of the absence, not to the assessment after one year."]], "1i.2"],
["How does the Sickness Benefits Act relate to the WIA for a safety-net employee who remains sick long term?", [["The period of ZW benefit counts towards the 104-week waiting period for the WIA", "A waiting period of two years also applies to safety-net employees; the ZW period fills that waiting period."], ["After the ZW, the safety-net employee must first wait another two years for the WIA", "The ZW period is precisely the waiting period; no second waiting period follows."], ["A safety-net employee never has a right to a WIA benefit", "After the waiting period, safety-net employees can receive a WIA benefit just like other employees."], ["The ZW always continues until the AOW (state pension) age", "The ZW is temporary and lasts a maximum of two years; the WIA may follow after that."]], "1i.2"],
["What is a 'ZW own-risk bearer' (eigenrisicodrager voor de Ziektewet)?", [["An employer who itself pays the ZW benefits and reintegration of sick former flex workers", "A ZW own-risk bearer does not pay differentiated ZW premium to the UWV, but bears the risk itself for the safety-net employees who come from it."], ["An employee who finances his own wages in the first two years of sickness through his own insurance", "Employees cannot become a ZW own-risk bearer; that is a choice for the employer."], ["A self-employed person who has not taken out disability insurance (AOV)", "Such a self-employed person effectively bears their own risk, but has nothing to do with the ZW."], ["An insurer that administers the ZW benefits on behalf of the UWV for small employers", "An insurer can insure the employer's risk, but the employer remains the own-risk bearer."]], "1i.13"],
["How does the UWV determine the degree of incapacity for work for the WIA?", [["By comparing the pre-sickness income (maatmaninkomen) with residual earning capacity", "The loss of earning capacity relative to the pre-sickness income determines the degree of incapacity for work."], ["By dividing the number of hours the employee still works by the number of hours in his employment contract", "The WIA looks at earning capacity, not merely at the number of hours worked."], ["Solely on the basis of the opinion of the treating specialist", "The medical limitations are input; the percentage only follows from the labour-expert comparison of incomes."], ["By converting the duration of the sickness period in weeks into a percentage of the waiting period", "How long someone has been sick says nothing about the degree of incapacity for work."]], "1g.14"],
["What is the 'maatmaninkomen' (pre-sickness income) in the WIA?", [["The income the employee earned before becoming sick", "The maatmaninkomen is the starting point against which the remaining earning capacity is measured."], ["The income an average employee in the Netherlands earns", "It concerns the employee's own income, not a national average."], ["The income the employee can still earn after his sickness", "That is the residual earning capacity, the other side of the comparison."], ["The minimum wage that applies for the employee's age", "The minimum wage plays a role in the WGA follow-up benefit, but it is not the maatmaninkomen."]], "1g.14"],
["Ahmed (44) is a bus driver and earned €3,300 gross per month. He is married and has three children. After a heart attack he can no longer work as a driver, but can do lighter work. After two years of sickness the UWV determines that he is 28% incapacitated for work. What does this mean for the WIA?", [["Ahmed has no right to a WIA benefit", "Below 35% incapacity for work there is no right to a WIA benefit; Ahmed is expected to use his remaining capacity."], ["Ahmed receives a WGA benefit pro rata to 28%", "The WGA only starts from 35% incapacity for work."], ["Ahmed receives an IVA benefit because he has been sick for more than two years", "The IVA is only for people who are fully and permanently incapacitated for work (80% or more)."], ["Ahmed receives the Sickness Benefits Act benefit for as long as he has not recovered", "The ZW does not continue after the WIA assessment for an employee with an employer."]], "1d.5"],
["Who is entitled to a WGA benefit?", [["Anyone who is at least 35% incapacitated for work, but not fully and permanently", "The WGA is intended for the partially incapacitated and for the fully incapacitated with a prospect of recovery."], ["Only those who are fully and permanently incapacitated for work", "The fully and permanently incapacitated fall under the IVA."], ["Everyone who is still sick after the 104-week waiting period, regardless of the percentage", "There is a lower limit of 35% incapacity for work."], ["Only employees who are still employed by their own employer after the waiting period", "Even someone who is no longer employed can be entitled to a WGA benefit."]], "1i.12"],
["Lotte (36) is a nurse in a hospital and earned €3,600 gross per month. She is single and has an eight-year-old son. After intensive treatment for a serious illness she is 85% incapacitated for work in the WIA assessment. According to the UWV insurance physician, recovery is quite possible in due course. Which benefit does she receive?", [["A WGA benefit", "Because the incapacity for work is not permanent, Lotte falls under the WGA and not the IVA despite the high percentage."], ["An IVA benefit", "In addition to 80% or more incapacity for work, the IVA requires that recovery is not, or hardly, to be expected."], ["No benefit, because recovery is possible", "A prospect of recovery does not rule out a benefit; it only determines which scheme applies."], ["A Wajong benefit", "The Wajong is for people who became incapacitated for work at a young age; that does not apply to Lotte."]], "1i.11"],
["How high is the IVA benefit?", [["75% of the (capped) daily wage", "The IVA amounts to 75% of the daily wage, where the daily wage is limited to the maximum daily wage."], ["70% of the minimum wage", "A percentage of the minimum wage belongs to the WGA follow-up benefit, not to the IVA."], ["100% of the last-earned wage", "The IVA does not top up to the full wage; moreover, a maximum daily wage applies."], ["70% of the difference between the daily wage and the residual earning capacity", "This calculation resembles the wage supplement benefit in the WGA, not the IVA."]], "1i.11"],
["What does the duration of the wage-related WGA benefit depend on?", [["On the employment history, in the same way as for the WW", "Like the WW, the wage-related phase lasts shorter or longer depending on the employment history."], ["On the degree of incapacity for work determined by the UWV", "The percentage determines whether someone falls under the WGA, but not how long the wage-related phase lasts."], ["On age: the benefit continues until the AOW age", "The wage-related phase is in fact temporary; the follow-up phase comes after it."], ["On the amount of the maatmaninkomen", "The maatmaninkomen determines the percentage, not the duration of the wage-related benefit."]], "1i.12"],
["Case: Mark receives a WGA benefit. His wage-related benefit ends. He uses less than half of his residual earning capacity. Which benefit does he receive afterwards?", [["A WGA follow-up benefit, based on a percentage of the minimum wage", "Anyone who insufficiently uses their residual capacity receives a follow-up benefit that depends on the incapacity class and the minimum wage; this is often a substantial drop in income."], ["A wage supplement benefit of 70% of the difference between the maatmaninkomen and the residual earning capacity", "The wage supplement benefit is only for those who use at least half of their residual earning capacity."], ["An IVA benefit of 75% of the daily wage", "The end of the wage-related phase changes nothing about whether someone is permanently and fully incapacitated for work."], ["An extended wage-related benefit until the AOW age", "The wage-related phase is limited in duration and cannot be extended until the AOW age."]], "1g.15"],
["What condition applies to the WGA wage supplement benefit?", [["He must use at least half of his remaining earning capacity", "Anyone who works enough receives a supplement based on their own wage; this encourages a return to work."], ["The employee must be fully incapacitated for work", "A fully incapacitated person has no residual earning capacity to use."], ["The employee must be younger than 50", "No age limit applies to the wage supplement benefit."], ["The employee must have been employed by the same employer for at least ten years", "The length of employment with one employer is not a condition."]], "1g.15"],
["What is the main reason a WGA beneficiary can suffer a large loss of income after the wage-related phase?", [["With insufficient use of capacity, the follow-up benefit is based on the minimum wage, not on the own wage", "This income gap is called the WGA gap and is the reason the WGA gap insurance exists."], ["The WGA benefit is always stopped after the wage-related phase, regardless of how much someone still works", "The benefit does not stop, but is calculated differently in the follow-up phase."], ["From that moment the employer must reclaim the wages paid earlier", "An employer has no right to reclaim wages paid earlier."], ["From the follow-up phase the UWV offsets the employee's own assets and savings against the benefit", "There is no means test in the WGA; one does apply in social assistance."]], "1i.12"],
["What threshold is applied in the WIA to be 'fully' incapacitated for work?", [["80% or more", "From 80% incapacity for work someone is fully incapacitated; if it is permanent the IVA follows, otherwise the WGA 80-100."], ["Exactly 100%", "Someone who does not lose 100% of earning capacity can also count as fully incapacitated for work."], ["65% or more", "65% is not a threshold in the WIA."], ["35% or more", "35% is the lower limit for a WIA benefit, not the limit for full incapacity for work."]], "1i.11"],
["Ilse (24) had been employed for only five months as a sales assistant at a fashion shop after her studies when she became sick. She earned €2,300 gross per month and lives with her boyfriend. Before that she had never worked in paid employment. After two years of sickness she is declared 40% incapacitated for work and it turns out that she does not meet the qualifying requirement (referte-eis). What does this mean for her WGA benefit?", [["She skips the wage-related phase and goes straight to the follow-up phase", "Anyone who does not meet the qualifying requirement has no right to the wage-related benefit and goes straight to the follow-up phase."], ["She receives no WIA benefit at all", "Failing the qualifying requirement only rules out the wage-related phase, not the entire WGA."], ["She receives an IVA benefit of 75% of the daily wage as compensation", "The IVA depends on full and permanent incapacity for work, not on the qualifying requirement."], ["She must first receive a Sickness Benefits Act benefit for another year before the WGA starts", "The qualifying requirement says nothing about an additional period under the Sickness Benefits Act."]], "1i.12"],
["Who is a '35-minner' (person under 35% incapacity) in the WIA?", [["An employee who is less than 35% incapacitated for work after the waiting period", "This employee receives no WIA benefit; the employer is expected to offer suitable work or the employee can look for work elsewhere."], ["An employee who is younger than 35 and already receives a WIA benefit", "The term refers to the degree of incapacity for work, not to age."], ["An employee who works fewer than 35 hours per week", "The number of contractual hours is unrelated to this term."], ["An employee who has been sick for fewer than 35 weeks before the WIA application", "The term has nothing to do with the duration of sickness."]], "1d.5"],
["What applies to the earning capacity that the UWV determines for the WIA?", [["The UWV assumes designated jobs he can still perform, even without a job", "The assessment is based on designated jobs in the labour market, regardless of whether the employee finds a job."], ["The UWV looks only at suitable jobs available with the own employer", "The WIA assessment takes the entire labour market into account, not only the own employer."], ["The UWV assumes the work the employee most wants to do after recovery", "Personal preference plays no role; what matters is what he can still do."], ["The UWV looks only at the own occupation the employee practised before sickness", "An own-occupation incapacity criterion belongs to some private AOV policies, not to the WIA."]], "1g.16"],
["Who is the Wajong intended for?", [["Anyone who became incapacitated for work before turning 18 or during studies", "The Wajong is for the young disabled: anyone who becomes long-term sick or disabled before turning 18, or during studies before turning 30."], ["Employees who do not fully recover from their condition after two years of sickness", "They fall under the WIA, not the Wajong."], ["Self-employed people under 30 without AOV", "Self-employment does not give a right to the Wajong."], ["Young people who cannot find a job after completing their education", "Unemployment without incapacity for work gives no right to the Wajong."]], "1i.2"],
["What has applied since 2015 to new entrants to the Wajong?", [["Only those with permanently no earning capacity can still receive Wajong", "Since the introduction of the Participation Act, the Wajong is limited to young disabled people without earning capacity; others fall under the municipality."], ["Every young disabled person receives a Wajong benefit until the age of 27", "There is no longer a general Wajong benefit for every young disabled person."], ["The Wajong was abolished entirely in 2015", "The Wajong still exists, but only for a limited group."], ["Since 2015 the Wajong has been administered by the SVB", "The Wajong is administered by the UWV."]], "1i.2"],
["An employer takes out new absenteeism insurance. One employee is already sick on the start date. How does an insurer generally deal with this run-in risk (inlooprisico)?", [["Current absence is excluded, unless run-in has been expressly insured", "An insurer prefers not to cover a risk that has already materialised. Current cases of sickness therefore usually fall outside the cover or only under separate conditions."], ["Current absence is always covered from the first day of sickness", "An employer would then only take out insurance once someone is already sick; this is why insurers usually exclude current absence."], ["The employer may only insure that employee once he is in the WIA", "The WIA follows after two years; absenteeism insurance covers precisely the period before that."], ["The insurer refuses the entire employer as policyholder", "A current case of sickness usually leads to exclusion of that case, not to refusal of the entire policy."]], "1g.12"],
["What is the qualifying requirement (referte-eis) in the WW?", [["Having worked at least 26 weeks in the 36 weeks before unemployment", "Anyone who meets the qualifying requirement is entitled to a basic WW benefit."], ["Having worked at least four years in the five years before unemployment", "That resembles the years requirement, which determines whether someone is entitled to a longer WW."], ["Having been employed by the last employer for at least one year", "The qualifying requirement looks at weeks worked, regardless of which employer."], ["Having paid WW premium oneself for at least 26 weeks", "The WW premium is paid by the employer; the qualifying requirement concerns weeks worked."]], "1i.2"],
["Jeroen (31) is an employed IT consultant and earns €4,200 gross per month. He is single and has no children. Without an urgent reason he resigns from his permanent job himself to go travelling for two months. After returning he does not immediately find other work and applies for WW. What is the starting point?", [["He has no right to WW, because he is culpably unemployed", "Anyone who resigns without good reason is culpably unemployed and receives no WW."], ["He has a right to WW, but only after a waiting period of three months", "A waiting period does not replace the loss of entitlement; with culpable unemployment there is no benefit."], ["He has a right to WW, because he meets the qualifying requirement", "Meeting the qualifying requirement is not enough if the unemployment is culpable."], ["He has a right to half a WW benefit", "A partial benefit is not the sanction for culpable unemployment."]], "1i.2"],
["How is income from work offset during a WW benefit?", [["70% of the income is offset against the WW", "Because only 70% is offset, it pays to work (part-time) during the WW."], ["The income earned is deducted in full", "Full offsetting would discourage working; the WW offsets 70%."], ["Income from work is not offset", "Income from work during the WW is certainly offset."], ["The WW stops as soon as any income is earned", "The WW does not stop immediately; offsetting takes place and the benefit only ends when income is sufficient."]], "1i.2"],
["A self-employed person has income insurance with indemnity cover with two insurers, which both cover the same loss of income. What does this concurrence mean for the settlement of the claim?", [["He receives in total no more than his actual loss; the insurers divide it between themselves", "With concurrence of indemnity insurances, the insured may not profit from the loss (principle of indemnity). The insurers bear the loss proportionally."], ["Both insurers pay the full amount, so that he receives double", "That is possible with sum insured policies, but not with indemnity insurance."], ["Only the insurance taken out most recently pays out", "There is no rule that the youngest policy takes precedence; the law and the concurrence provisions regulate the division."], ["Neither pays out, because double insurance is prohibited", "Double insurance is not prohibited; it just does not lead to a higher payout than the loss."]], "1k.4"],
["Fatima (39) is a doctor's assistant at a health centre and earns €2,600 gross per month for 32 hours per week. She is married and has two children at primary school. She has worked continuously for the same employer for years. Due to a reorganisation, 12 of her 32 contractual hours per week lapse, while the rest of her job is retained. Can she in principle receive WW?", [["Yes, she loses at least five hours a week and can get WW for them", "Partial unemployment can also give a right to WW if the loss of hours is large enough and the other conditions are met."], ["No, WW is only possible if all contractual hours lapse at the same time", "The WW also recognises partial unemployment."], ["No, she must first lose at least half of her contractual hours per week", "That halving rule only applies to employees who worked fewer than ten hours per week."], ["Yes, but only if she is older than 50", "Age is not a condition for the right to WW."]], "1i.2"],
["Peter (45) was a lorry driver and is married to Marieke (43). Marieke works full-time as a teacher and earns €4,000 gross per month. Their children are 19 and 21 years old. Peter suddenly dies of cardiac arrest; Marieke is not incapacitated for work. Is Marieke entitled to an Anw benefit?", [["No, there is no child under 18 and she is not incapacitated for work", "Without a child under 18, without 45% incapacity for work and born after 1950, Marieke has no right to an Anw surviving dependants' benefit."], ["Yes, every surviving partner receives an Anw benefit until the AOW age", "The Anw has strict eligibility conditions; not every partner is entitled."], ["Yes, but only until the youngest child reaches the age of 21", "The age limit for children in the Anw is 18, and that has already been passed here."], ["Yes, because she earns less than Peter", "An income difference between partners gives no right to the Anw."]], "1i.2"],
["Which income is NOT offset against an Anw surviving dependants' benefit?", [["A benefit from a private ORV (term life insurance)", "Benefits from a private ORV are not reduced against the Anw; an ORV can therefore be combined well with an Anw entitlement."], ["Income from employment or self-employment", "Income from work is (partly) offset against the Anw benefit."], ["A WIA benefit after long-term incapacity for work", "Benefits that replace income from work are offset in the Anw."], ["A ZW benefit during sickness as a safety-net employee", "A ZW benefit also replaces wages and is offset against the Anw."]], "1i.2"],
["What does a regret-opt-in scheme (spijtoptantenregeling) in a collective employee insurance, such as a WGA gap insurance with an employee contribution, regulate?", [["Employees who previously declined to participate can later join under conditions", "Such a scheme gives a second chance to join. The insurer usually attaches conditions, such as a health declaration or a time limit, to prevent adverse selection."], ["Employees can join retroactively after incapacity for work has arisen", "Joining after the risk has materialised would undermine the insurance principle."], ["Employers can terminate the collective policy without a notice period", "A regret-opt-in scheme concerns employees who want to join later, not termination by the employer."], ["Employees get their paid premium back if they never become incapacitated for work", "A risk insurance has no premium refund if there is no loss."]], "1h.10"],
["What happens to an Anw surviving dependants' benefit if the surviving partner starts cohabiting or remarries?", [["The benefit stops", "With a new marriage or cohabitation with a new partner, the right to Anw ends."], ["The benefit continues unchanged", "A new relationship with a joint household in fact ends the entitlement."], ["The benefit is halved", "There is no halving; the entitlement ends."], ["The benefit passes to the new partner", "An Anw benefit is personal and never passes to a new partner."]], "1i.2"],
["Up to what age is an orphan in principle entitled to an Anw orphan's benefit?", [["Up to 16 years; up to 21 years in case of study or incapacity for work", "After age 16 the orphan's benefit only continues in cases such as education or incapacity for work, up to a maximum of 21 years."], ["Up to 18 years, regardless of whether the orphan is still studying, working or incapacitated for work", "18 years is the age limit for the child in the partner's surviving dependants' benefit, not in the orphan's benefit."], ["Up to 27 years if the orphan follows a full-time course of study", "27 years is not a limit in the Anw."], ["For life if both parents have died (full orphan)", "The orphan's benefit is always temporary."]], "1i.2"],
["What is an Anw gap insurance for?", [["To cover the gap if Anw entitlement is absent or limited", "An Anw gap insurance pays out on death and tops up the missing Anw entitlement, often offered through the pension scheme."], ["To cover the difference between WW and the last-earned wage", "That gap has nothing to do with death and is not covered by an Anw gap insurance."], ["To increase the AOW of the surviving partner", "The Anw gap insurance generally stops at the AOW age and does not increase the AOW."], ["To pay funeral costs", "Funeral costs are covered by a funeral insurance."]], "1g.22"],
["After assessing the health declaration, an insurer can accept an application for disability insurance for the self-employed (AOV) in various ways. Which decision is NOT a customary acceptance decision?", [["Acceptance on condition that the client takes out no other insurances", "Such a condition does not belong to medical acceptance. Customary are standard acceptance, a premium surcharge, an exclusion, an adjusted waiting period or rejection."], ["Acceptance with an exclusion clause for a pre-existing condition", "An exclusion is a common acceptance decision for a known condition."], ["Acceptance at a premium surcharge", "A premium surcharge is a customary way to accept an increased risk after all."], ["Acceptance with a longer waiting period or a limited benefit period", "An adjusted waiting period or benefit period also occurs as a restrictive condition."]], "1h.1"],
["How much AOW accrual does someone miss for each year that he did not live or work in the Netherlands in the 50 years before his AOW age?", [["2% per year", "The AOW accrues over 50 years, at 2% per insured year; each uninsured year costs 2% of the full AOW."], ["1% per year", "At 1% the accrual would take 100 years; the AOW period is 50 years."], ["5% per year", "5% per year does not fit an accrual period of 50 years."], ["Nothing, the AOW is always paid in full", "Anyone who was not insured receives a reduced AOW."]], "1i.2"],
["May an employer recover from his employees the WGA premium that he pays as part of the Work Resumption Fund premium (premie Werkhervattingskas)?", [["Yes, he may recover at most half of the WGA premium from the employee's net wage", "The law permits recovery of at most half of the WGA premium; this does not apply to the remaining part of the Work Resumption Fund premium."], ["Yes, the full premium may be withheld from the gross wage", "Recovery is limited to at most half of the WGA premium."], ["No, all premiums for employee insurances are always borne entirely by the employer", "For the WGA premium there is in fact an exception that allows partial recovery."], ["Only if the employee earns more than the maximum daily wage", "The level of the wage does not determine whether recovery is permitted."]], "1i.3"],
["Hans is a technical draughtsman and reaches the AOW age this year. He earned €3,800 gross per month and will receive a modest pension on top. His wife Ellen is eight years younger and has no income of her own. Their children already live independently. What is the starting point for their AOW?", [["Hans receives an AOW for married people; there is no longer a partner supplement for Ellen", "The AOW partner supplement was abolished as of 2015; the household may therefore have an income gap until Ellen herself receives AOW."], ["Hans receives an AOW for single people until Ellen reaches the AOW age", "Married people receive the AOW for married people, even if the partner does not yet receive AOW."], ["Ellen also receives AOW immediately because her husband receives AOW", "AOW is a personal right that starts at one's own AOW age."], ["Hans receives a partner supplement from the SVB until Ellen receives AOW", "The partner supplement no longer exists for anyone who became entitled to AOW after 2014."]], "1i.2"],
["What is the increase in the AOW age based on?", [["On the development of life expectancy", "The AOW age is legally linked to the average remaining life expectancy and is set several years in advance."], ["On the level of inflation", "Inflation influences the level of the AOW amounts, not the AOW age."], ["On the funding ratio of pension funds", "The funding ratio concerns pension funds, not the AOW."], ["On the number of years the person has worked", "The AOW age is the same for everyone with the same date of birth."]], "1i.2"],
["Which incapacity criterion in a disability insurance for the self-employed (AOV) offers the self-employed person the broadest cover?", [["Own-occupation incapacity", "Under this criterion the insured is already incapacitated if he can no longer practise his own occupation, even if he can still do other work."], ["Suitable-work incapacity", "With suitable work, other work that fits education and experience is also considered; that is narrower than the own occupation."], ["Generally accepted-work incapacity", "With generally accepted work, the test is against almost all generally accepted work; that is the narrowest criterion."], ["Incapacity according to the WIA standard", "The WIA standard looks at the entire labour market and is therefore in fact restrictive for the insured."]], "1g.8"],
["Floor (42) is a self-employed dentist with her own practice and makes €110,000 profit per year. She is married and has two children. Because of a complex hand injury she can no longer perform treatments. She could work as a lecturer in dentistry at a training programme. With which AOV cover is she most likely to receive a benefit?", [["With cover based on own-occupation incapacity", "Floor can no longer practise her own occupation; with own-occupation cover that is sufficient for a benefit."], ["With cover based on suitable work", "Work as a lecturer in dentistry fits her education and experience, as a result of which suitable-work cover may not pay out, or pay out less."], ["With cover based on generally accepted work", "With generally accepted work, other general work is also considered; that covers her situation the least."], ["With every cover to the same extent, because the criterion makes no difference", "The incapacity criterion in fact determines against which work Floor is assessed, and therefore whether and how much is paid out."]], "1g.16"],
["What is the effect of a longer waiting period (excess period) in an AOV?", [["Lower premium, but the insured must bridge the first period himself", "A longer waiting period reduces the risk for the insurer; the self-employed person must have a sufficient buffer."], ["The premium becomes higher, because the insurer must pay out over a longer period", "With a longer waiting period the benefit starts later; the premium in fact falls."], ["The benefit becomes higher as compensation for waiting", "The level of the benefit depends on the insured amount, not on the waiting period."], ["Nothing changes in premium or cover", "The waiting period is an important premium-determining factor."]], "1g.8"],
["Dirk (38) is a self-employed plumber and makes €52,000 profit per year. He lives with a partner and their daughter is three. He has built up a savings buffer with which he can pay six months of fixed costs. When taking out his AOV he wants to pay as little premium as possible. Which choice is the most obvious?", [["Choose a longer waiting period that fits his buffer", "With his buffer Dirk can bridge the first months himself; a longer waiting period lowers the premium considerably."], ["Choose the shortest possible waiting period", "A short waiting period gives the highest premium, while Dirk then does not use his buffer."], ["Set the insured amount higher than his income", "Over-insurance raises the premium and is limited by insurers."], ["Choose the end age of the AOV as high as possible", "A higher end age extends the cover, but in fact raises the premium."]], "1g.8"],
["Why do insurers generally not accept an insured amount in an AOV that is equal to or higher than the full income?", [["To prevent over-insurance and to retain the incentive to return to work", "If a benefit is as high as or higher than the income, the financial incentive to go back to work disappears."], ["Because the Wft prescribes a maximum of 50% of income", "The Wft does not prescribe a maximum percentage for the insured amount."], ["Because the Tax Administration does not permit a higher benefit", "There is no tax prohibition; the maximum is an acceptance policy of insurers."], ["Because otherwise the premium is not deductible", "The deductibility of the premium does not depend on the ratio between insured amount and income."]], "1g.6"],
["What is the difference between an AOV as a sum insured policy and as an indemnity insurance?", [["Sum insured: a pre-agreed amount; indemnity: compensation of the actual loss of income", "With an indemnity insurance the insured must demonstrate the loss of income; with a sum insured policy the benefit depends on the insured amount and the degree of incapacity."], ["A sum insured policy only pays out on death", "Paying out on death is characteristic of an ORV, not of the difference between sum insured and indemnity insurance."], ["With an indemnity insurance the premium is always tax-deductible and with a sum insured policy never", "The tax treatment does not depend on this distinction."], ["An indemnity insurance never has a waiting period", "An AOV on an indemnity basis also has a waiting period."]], "1f.2"],
["What does a health clause (exclusion) in an AOV mean?", [["Incapacity for work due to a condition known in advance is not covered", "With an existing health risk, the insurer can accept the cover with exclusion of that condition."], ["The insured must undergo an annual medical examination with the insurer", "An annual examination is not a standard part of an AOV or an exclusion."], ["The insurer may cancel the policy at any time", "An exclusion concerns the cover, not a right of cancellation."], ["The premium is always doubled", "A premium surcharge is a different instrument from an exclusion and is not a fixed doubling."]], "1h.1"],
["Jan (50) is a self-employed painter and makes €45,000 profit per year. He is married and his children no longer live at home. His AOV only pays out from 25% incapacity for work. After a shoulder injury the insurer determines that he is 20% incapacitated for work. What is the consequence?", [["Jan receives no benefit, because he stays below the policy threshold", "The benefit only starts when the minimum incapacity percentage agreed in the policy is reached."], ["Jan receives 20% of the insured amount, pro rata to his incapacity for work", "Below the policy threshold nothing is paid out, not even pro rata."], ["Jan receives 25% of the insured amount, the minimum under the policy", "A benefit at the threshold itself does not exist; he is less incapacitated than the threshold."], ["Jan receives a benefit from the WIA", "As a self-employed person, Jan is generally not insured for the WIA."]], "1g.3"],
["What is a broodfonds (a mutual support fund)?", [["Self-employed people who temporarily support each other via gifts when sick", "A broodfonds is not an insurance; participants pay in monthly and give a sick participant a temporary income as a gift."], ["A mandatory public AOV for the self-employed, administered by the UWV", "A broodfonds is voluntary and organised by the participants themselves."], ["An AOV from an insurer with a short benefit period of a maximum of two years", "A broodfonds is not an insurance product of an insurer."], ["A savings account at the bank for entrepreneurs", "A broodfonds works as a collective of gifts, not as an individual savings account."]], "1d.6"],
["Ruud (47) is a director-major shareholder (dga) of his own consultancy and pays himself €85,000 per year in salary through the private limited company (bv). He is married and has two teenagers. Because he has control in the bv, he is not insured for the employee insurances. He asks what happens if he becomes sick long term. What follows from this for his income advice?", [["He falls outside the ZW and WIA and must arrange his incapacity risk himself", "A dga who is not insured for the employee insurances falls outside the ZW, WIA and WW; an AOV is then the obvious solution."], ["The bv is obliged to continue paying him wages for two years and then a WIA benefit from the UWV follows", "Without employee insurances there is no WIA after two years."], ["In case of incapacity for work he receives a Wajong benefit", "The Wajong is for the young disabled and is not intended for a dga."], ["He is automatically insured through the AOW", "The AOW is an old-age provision and does not cover incapacity for work."]], "1a.8"],
["In broad terms, what is the intention of the planned basic insurance for incapacity for work for the self-employed?", [["A mandatory public basic cover around minimum-wage level, with room to top up privately", "The government is working on a mandatory basic cover for the self-employed; for income above that level or a shorter waiting period a private AOV remains necessary. Check the current status of the bill."], ["A mandatory private occupation-based AOV for all self-employed people, to be provided by insurers", "The basic insurance is a public scheme and not a mandatory private own-occupation cover."], ["A voluntary savings scheme via the Tax Administration", "It concerns an insurance against long-term incapacity for work, not a savings scheme."], ["An extension of the Wajong to all self-employed people without their own AOV", "The Wajong remains for the young disabled; the basic insurance is a separate scheme."]], "1i.7"],
["Noor (33) is a self-employed photographer and makes €40,000 profit per year. She lives with a partner and is expecting her first child. She has an AOV, but reads that a mandatory basic insurance for incapacity for work for the self-employed is coming. To save premium she asks whether she can cancel her AOV now. What is careful advice?", [["Do not cancel: the scheme is not in force yet and will only offer a basic level after a long wait", "As long as the scheme is not in force, Noor is not insured; even afterwards a top-up is often needed for income above the basic level and for the first period."], ["Cancel, because the basic insurance gives retroactive cover from the announcement", "There is no indication that the scheme offers retroactive cover."], ["Cancel, because the basic insurance replaces the full income", "The planned benefit is in fact a basic level and does not fully replace a higher income."], ["Cancel and save the money, because participation in a broodfonds will become legally mandatory for freelancers", "A broodfonds will not become legally mandatory."]], "1i.7"],
["What does a WIA excess insurance (WIA-excedentverzekering) cover?", [["The loss of income on the part of the wage above the maximum daily wage", "The WIA only insures wages up to the maximum daily wage; the excess insurance covers the loss on the excess."], ["The loss of income during the first two years of sickness", "In the first two years the employer continues to pay wages; the excess insurance does not cover that gap."], ["The loss of income on unemployment above the WW", "Unemployment falls outside the WIA excess insurance."], ["Funeral costs on death after incapacity for work", "Funeral costs are covered by a funeral insurance."]], "1g.13"],
["Marloes (45) is a financial manager at a construction company and earns €9,000 gross per month, well above the maximum daily wage. She is divorced and cares for two children. Her employer offers a collective WGA gap insurance, but no WIA excess insurance. She asks what happens if she becomes incapacitated for work long term. Which risk remains for her?", [["Her wage above the maximum daily wage is uninsured on incapacity for work", "The WGA gap insurance fills the gap up to the level of the (capped) WIA wage; for the wage above that, excess cover is needed."], ["She is not insured during the first two years of sickness", "In the first two years the employer's continued payment of wages applies."], ["She receives no WGA benefit, because her wage is above the maximum daily wage", "A high income does not rule out the WGA; only the daily wage is capped."], ["Her WGA gap insurance lapses with a high income", "A high income is not a ground for lapse of the WGA gap insurance."]], "1g.13"],
["When does a WGA gap insurance generally pay out?", [["When the employee receives a benefit at minimum-wage level in the WGA follow-up phase", "The WGA gap insurance tops up the often low follow-up benefit; this is the WGA gap."], ["From the first day of sickness", "In the first two years there is continued payment of wages and no WGA yet."], ["Only with an IVA benefit", "With the IVA there is no WGA follow-up phase, and so no WGA gap."], ["Only if the employee is declared less than 35% incapacitated for work after the waiting period", "Below 35% there is no WGA benefit; separate 'WIA 35-min' covers exist for that."]], "1g.13"],
["How is a benefit from a collective WIA excess insurance that runs through the employer generally treated for tax purposes?", [["As taxable income in box 1", "Benefits that replace income are taxed as income; with an employer scheme often as wages."], ["As a tax-free compensation for damages", "An income-replacing benefit is not a tax-free compensation for damages."], ["As assets in box 3", "Box 3 does not apply to periodic income-replacing benefits."], ["As income from a substantial interest in box 2", "Box 2 concerns income from a substantial interest, such as dividend."]], "1i.10"],
["What does an absenteeism insurance (verzuimverzekering) cover?", [["The employer's wage continuation risk during employee sickness", "An absenteeism insurance reimburses the employer (part of) the wages continued during the first two years of sickness."], ["The employee's WIA benefit once the two-year waiting period has elapsed", "After two years there is no longer absenteeism but WIA; other insurances exist for that."], ["The loss of income of a self-employed person during sickness", "A self-employed person insures with an AOV, not with an absenteeism insurance."], ["The employee's costs of medical treatment", "Medical costs fall under health insurance."]], "1g.10"],
["Henk (56) has a bakery with five employees and keeps €60,000 profit per year from it himself. He is married and his son helps out in the business. Last year an employee was sick for three months; that cost Henk a lot of money, also for a temp. He doubts whether he needs absenteeism insurance. Which argument weighs the heaviest?", [["One long-term sick employee costs him up to two years of wages, plus often a replacement", "For a small employer, one long-term sick employee can be a large financial burden; an absenteeism insurance spreads that risk."], ["An absenteeism insurance is legally mandatory for every employer", "An absenteeism insurance is not mandatory; the employer can also bear the risk himself."], ["Without absenteeism insurance he does not have to continue paying wages", "The obligation to continue paying wages applies regardless of whether the employer is insured."], ["An absenteeism insurance takes over the obligations under the Gatekeeper Improvement Act", "The reintegration obligations remain in force, even if the employer is insured."]], "1b.1"],
["What does a stop-loss absenteeism insurance mean?", [["The employer bears the absence itself up to a maximum amount; the insurer pays the excess", "Stop-loss protects the employer against outliers, while he pays the 'normal' absence himself."], ["The insurer reimburses all absence costs from the first day", "Full reimbursement from day one is not stop-loss, but extended cover without an excess."], ["The insurance stops automatically as soon as an employee has remained sick for longer than a year", "Stop-loss refers to limiting the loss, not to stopping the cover."], ["The employee pays the premium through his wages and the employer receives the benefits on absence", "The premium for an absenteeism insurance is borne by the employer."]], "1g.11"],
["What does own-risk bearing for the WGA (eigenrisicodragerschap) mean?", [["The employer itself pays the WGA benefits for up to ten years and arranges the reintegration", "The employer then pays no differentiated WGA premium to the UWV, but bears the risk itself; this is often insured."], ["The employee pays his own WGA benefit", "Own-risk bearing is a choice of the employer and places no costs on the employee."], ["The employer itself bears the risk of the IVA benefits of its (former) employees", "Own-risk bearing concerns the WGA; the IVA remains with the UWV."], ["The employer no longer has to continue paying wages to sick employees during the first two years of sickness", "The obligation to continue paying wages in the first two years remains fully in place."]], "1i.13"],
["What does an employer need to become a WGA own-risk bearer?", [["A guarantee statement from an insurer or bank", "The guarantee statement ensures that the benefits continue, even if the employer can no longer pay."], ["A licence from the AFM", "The AFM does not grant licences for own-risk bearing."], ["Written consent from each individual employee", "Individual consent from employees is not required."], ["A minimum of 100 employees", "Smaller employers can also become own-risk bearers."]], "1f.9"],
["What does a housing costs insurance (woonlastenverzekering) cover?", [["A temporary monthly benefit for housing costs on incapacity and/or unemployment", "A housing costs insurance helps to pay the mortgage costs temporarily; the scope and duration of cover differ per policy."], ["The full repayment of the mortgage on unemployment", "A housing costs insurance pays monthly amounts and does not repay the mortgage."], ["Damage to the home from fire or storm", "That is a buildings insurance."], ["The loss of income on incapacity for work, for life and up to the full gross income", "The benefit is limited in duration and amount and does not cover income for life."]], "1g.1"],
["How is a housing costs insurance generally treated for tax purposes?", [["The premium is not deductible and the benefit is untaxed", "Because the housing costs insurance is not an income provision in the tax sense, the premium is not deductible and the benefit is not taxed."], ["The premium is deductible and the benefit is taxed in box 1", "That treatment applies to an AOV, not to a housing costs insurance."], ["The premium is deductible as mortgage interest", "An insurance premium is not interest on an owner-occupied home debt."], ["The benefit falls in box 3", "A housing costs benefit is not taxed as assets in box 3."]], "1i.5"],
["Tom (35) is a self-employed gardener with €38,000 profit per year; his partner Lisa works part-time as a hairdresser. They have a purchased home and a two-year-old son. Tom has no AOV and sees a housing costs insurance as a cheaper alternative. They ask whether a housing costs insurance can replace an AOV. What is the correct starting point?", [["No, it covers only the housing costs and only temporarily; an AOV protects income long term", "For a self-employed person without employee insurances, a housing costs insurance is at most a supplement, not a replacement."], ["Yes, a housing costs insurance covers the same income risk as an AOV", "The cover differs greatly in scope and duration."], ["Yes, because a housing costs insurance, like an AOV, pays out until the AOW age", "Housing costs insurances generally pay out for a limited time."], ["No, because a housing costs insurance can only be taken out by employees in paid employment", "Self-employed people can also take out a housing costs insurance, with or without unemployment cover."]], "1g.1"],
["Mila de Wit (34) is a self-employed physiotherapist and makes €48,000 profit per year. She lives with a partner and has a two-year-old daughter. Her father died young of a hereditary heart muscle disease; last year she had a DNA test, which showed that she also has the predisposition. She has no complaints and is not under treatment or monitoring. She now applies for an AOV with an insured amount that stays below the statutory question limit (vragengrens). Must she report the result of her DNA test on the health declaration?", [["No, below the question limit the insurer may not ask about the result of genetic testing", "Below the question limit, questions about the result of genetic testing are not permitted, so Mila does not need to report it. She must, however, answer questions about her own complaints and treatments honestly."], ["Yes, the duty of disclosure applies to all facts that may be of importance to the insurer", "The duty of disclosure is limited: Mila does not need to report facts the insurer is legally not allowed to ask about."], ["Yes, but she may only pass the result on orally to her adviser", "Medical data do not belong with the adviser; moreover, below the question limit the result does not need to be reported at all."], ["No, an insurer may never ask about genetic testing, not even above the question limit", "That goes too far: above the question limit an insurer may in principle ask about the result of a previous genetic test."]], "1h.8"],
["Mark Verbeek (46) is a dga of an IT company and pays himself €120,000 per year in salary through the bv. He is married and has three children. He applies for an AOV with a high insured amount and a short waiting period. Because that amount is above the insurer's examination limit (keuringsgrens), the insurer asks for a medical examination in addition to the health declaration. Mark asks whether that is permitted and what happens with the result. What is correct?", [["That is permitted; Mark may hear the result first himself and can block its transmission to the insurer", "Above its examination limit an insurer may require an examination. The Medical Examinations Act gives Mark the right to be the first to learn the result and to block transmission; the insurer can then refuse the application."], ["That is not permitted; under the law a health declaration is always sufficient for an AOV", "There is no legal rule that a health declaration is always sufficient; with high amounts an additional examination is customary and permitted."], ["That is permitted; the examination report also goes to his adviser, who supports the acceptance", "Medical data go to the insurer's medical adviser and not to the client's adviser."], ["That is only permitted if his own GP carries out the examination", "A treating doctor generally does not examine his own patient; the examination is carried out by an independent examining doctor."]], "1h.8"],
["Iris Bakker (38) is a self-employed estate agent and makes €70,000 profit per year. She is married and has two children at primary school. Her father had a heart attack at 48 and her brother has hereditary high cholesterol. The health declaration for her AOV asks whether cardiovascular disease occurs in parents, brothers or sisters before a certain age. She herself has never had a DNA test. Must she report the conditions in her family?", [["Yes, if the health declaration expressly asks about it, she must answer the question truthfully", "The duty of disclosure applies to the questions the insurer asks. Iris must answer a question about illnesses in the family honestly, even though she herself has had no genetic testing."], ["No, data about family members never fall under the applicant's duty of disclosure", "If the insurer asks about illnesses in the family, the answer to that question does fall under the duty of disclosure."], ["No, only the result of her own DNA test is relevant to the insurer", "The restriction below the question limit concerns the result of genetic testing, not a question asked about illnesses in the family."], ["Only if her family members give written consent for it", "Iris answers the question with what she knows herself; consent of family members is not a condition for that."]], "1h.8"],
["Erwin Hendriks (52) is a self-employed electrician and makes €46,000 profit per year. He is married and his two children are studying. On the health declaration for his AOV he reports that he saw the cardiologist last year for heart rhythm disorders. The insurer wants to know more before taking an acceptance decision. How may the insurer obtain additional medical information?", [["Its medical adviser may request factual data from the cardiologist with Erwin's written consent", "Additional medical information goes through the insurer's medical adviser and only with the client's consent. The treating doctor provides factual data and gives no opinion on the insurance risk."], ["The underwriter may request the full medical file from the GP without consent", "Without Erwin's consent no medical information may be requested, and medical data go not to the underwriter but to the medical adviser."], ["Erwin's adviser calls the cardiologist and passes the information to the insurer", "An adviser should not collect or pass on medical information; that takes place between doctors."], ["The cardiologist must give an opinion on whether Erwin is insurable", "A treating doctor does not give an opinion on insurability; that is assessed by the insurer's medical adviser."]], "1h.8"],
["What is the difference between the question limit (vragengrens) and an examination limit (keuringsgrens) for an AOV?", [["The question limit is set by law; an examination limit is the insurer's acceptance policy", "The question limit follows from the Medical Examinations Act and applies to all insurers. Above which amount or from which age an additional examination is needed is decided by each insurer in its own acceptance guidelines."], ["Both limits are set annually by the AFM and apply to all insurers", "The AFM does not set these limits; the question limit is laid down in regulations and examination limits differ per insurer."], ["Above the question limit the insurer may no longer ask for a health declaration", "Above the question limit an insurer may in fact ask more, such as about the result of a previous genetic test."], ["The examination limit applies only to employees and the question limit only to the self-employed", "Both limits are related to the insured amount and the type of insurance, not to whether someone is an employee or self-employed."]], "1h.8"],
["May an insurer require an applicant for an AOV to take a genetic test (DNA test)?", [["No, it may not require the applicant to undergo genetic testing", "The Medical Examinations Act and the agreements in the Moratorium on Genetic Testing rule out such an obligation, even with high insured amounts."], ["Yes, if the insured amount is above the question limit", "Above the question limit the insurer may only ask about the result of a previous test; it may not require a new test."], ["Yes, if a hereditary disease occurs in the family", "A hereditary disease in the family also does not give the insurer the right to demand a DNA test."], ["Only if the medical adviser keeps the result secret from the underwriter", "Confidentiality changes nothing about the prohibition on requiring a genetic test."]], "1h.7"],
["An advisory firm receives an administrative fine from the AFM. Which route is open to the firm?", [["First lodge an objection with the AFM and then, if necessary, appeal to the administrative court", "Against a decision of the AFM, an objection with the AFM itself is open first. Appeal to the district court and further appeal to the Trade and Industry Appeals Tribunal (CBb) follow."], ["Lodge a complaint with Kifid, which can reduce or annul the fine", "Kifid settles disputes between clients and financial firms and cannot review fines of the AFM."], ["Go directly to cassation at the Supreme Court", "An AFM decision follows the administrative-law route of objection and appeal; going directly to the Supreme Court is not possible."], ["Submit a request to DNB to reassess the fine", "DNB and the AFM are each competent within their own supervision; DNB cannot revise an AFM fine."]], "1a.3"],
["What is the significance of the maximum daily wage (maximumdagloon) for the employee insurances?", [["It is the upper limit of the daily wage on which WW, ZW and WIA benefits are calculated", "Wage above the maximum daily wage does not count towards the benefit, which creates an income gap for higher incomes. The amount is adjusted periodically."], ["It is the minimum wage per day that an employer is obliged to pay", "The minimum wage is a lower limit for wages; the maximum daily wage in fact caps the basis of the benefit."], ["It is the highest amount that an AOV insurer may pay out", "A private AOV has its own maximum amounts; the maximum daily wage applies to the public employee insurances."], ["It is the maximum wage over which an employee may accrue pension", "Pension accrual has its own tax maximum; that is something different from the maximum daily wage."]], "1a.5"],
["Thijs Mulder (40) is a self-employed installer and makes €50,000 profit per year. He is married and has two children aged six and nine. The family has an annuity mortgage and a term life insurance (ORV), and Thijs saves for his pension through an annuity insurance (lijfrenteverzekering). During AOV advice he asks why his adviser also looks at those other products. What is the most important connection?", [["On incapacity for work the mortgage costs and premiums continue, unless a policy has premium waiver on incapacity", "Incapacity for work affects all fixed costs. The adviser therefore checks whether housing costs and ongoing premiums remain affordable and whether policies have premium waiver on incapacity for work."], ["On incapacity for work the mortgage and the ORV are automatically made premium-free by law", "There is no statutory premium waiver; it exists only if agreed in the policy."], ["An AOV benefit is offset against the benefit from his ORV", "An ORV pays out on death and is not offset against an AOV benefit."], ["There is no connection; AOV advice is separate from his other financial products", "Income advice in fact looks at the entire household budget, including the costs of other products."]], "1a.7"],
["By law an employer must continue to pay a sick employee at least 70% of wages. What can a collective labour agreement (cao) change about this?", [["A cao can agree higher continued payment of wages, for example 100% in the first year of sickness", "Many collective agreements top up the statutory 70%. That increases the obligation to continue paying wages and thus the risk that the employer may insure."], ["A cao can reduce the continued payment of wages below 70% if the employer is insured", "The statutory minimum cannot be deviated from to the employee's disadvantage."], ["A cao can provide that the employer does not have to pay anything in the second year of sickness", "In the second year too, at least the statutory 70% applies; a cao cannot remove that."], ["A cao has no influence on the continued payment of wages during sickness", "The cao is in fact an important source for the level of the obligation to continue paying wages."]], "1b.4"],
["An employer hires someone who falls under the Participation Act and, because of a disability, cannot earn the full minimum wage. Which scheme compensates the employer for the difference between the wage and the productivity value (loonwaarde)?", [["Wage cost subsidy via the municipality", "Wage cost subsidy under the Participation Act tops up the difference between the statutory minimum wage and the employee's determined productivity value."], ["A WGA gap benefit from the UWV", "A WGA gap benefit comes from an insurer on incapacity for work and is not a subsidy for the employer."], ["The transition payment (transitievergoeding)", "The transition payment is a payment to the employee on dismissal and has nothing to do with productivity value."], ["A ZEZ benefit", "The ZEZ benefit is intended for self-employed people during pregnancy and childbirth."]], "1b.6"],
["Why is the Uniform Pension Overview (UPO) useful in income advice on incapacity for work?", [["It shows whether the pension scheme provides a benefit or premium-free accrual on incapacity for work", "The UPO shows which provisions the pension scheme offers on incapacity for work, so that the adviser does not recommend double or missing cover."], ["It shows the amount of the WIA benefit that the UWV will award", "The UPO comes from the pension provider and contains no WIA decision of the UWV."], ["It replaces the income analysis, because all incapacity risks are on it", "The UPO only shows the pension scheme; other provisions and costs remain out of view."], ["It states the premium that the employee must pay for an AOV", "A private AOV is separate from the pension scheme and does not appear on the UPO."]], "1b.7"],
["How is the premium for a self-employed person's private AOV treated for tax purposes?", [["As a deductible expense for income provision in box 1", "The premium for an AOV is deductible in box 1; the benefit is then also taxed."], ["As a non-deductible consumption expense", "The AOV premium is in fact deductible."], ["As a cost that is only deductible in box 2", "A self-employed person with a sole proprietorship has no box 2 income from his business."], ["As an asset in box 3", "An AOV has no asset value in box 3."]], "1i.5"],
["How is a benefit from a private AOV treated for tax purposes?", [["As taxable income in box 1", "Because the premium is deductible, the benefit is taxed in box 1 as a periodic benefit."], ["As an untaxed compensation for damages", "An AOV benefit replaces income and is therefore taxed."], ["As assets in box 3", "A periodic income-replacing benefit does not fall in box 3."], ["As a taxable gift", "An insurance benefit is not a gift."]], "1i.5"],
["Bart (40) is a self-employed carpenter and makes an average of €60,000 profit per year. He is married and has three children. He wants to take out an AOV and has calculated the net disposable income on which the family gets by. He therefore wants to base the insured amount on that net amount. Why is that unwise?", [["Because the benefit is taxed, he must determine the insured amount on a gross basis", "The AOV benefit is taxed in box 1; anyone who insures on a net basis is left with too little after tax."], ["Because the premium is then no longer deductible", "Deductibility does not depend on the level of the insured amount."], ["Because insurers only accept insured amounts that are above average profit", "Insurers in fact limit the insured amount to a part of the profit."], ["Because an insured amount on a net basis always leads to over-insurance and thus wasted premium", "A net basis is more likely to lead to under-insurance."]], "1i.5"],
["Which combination of tax treatment belongs to an AOV, an ORV and a housing costs insurance?", [["AOV: deduction, taxed benefit; ORV, housing costs: no deduction, benefit not in box 1", "Only the AOV is an income provision in box 1; the ORV and the housing costs insurance have no premium deduction and no box 1 levy on the benefit."], ["All three: premium deductible in box 1 and benefit taxed as a periodic benefit", "The ORV and the housing costs insurance have no premium deduction."], ["All three: premium not deductible and benefit untaxed, because they are risk insurances", "For the AOV there is in fact premium deduction and a taxed benefit."], ["AOV and ORV: premium deductible and benefit taxed; housing costs insurance: neither", "The ORV premium is not deductible."]], "1i.5"],
["Which risks should in any case be addressed in an income analysis for mortgage advice?", [["Incapacity for work, unemployment, death and retirement", "A full income analysis shows the financial consequences of these events for the affordability of the housing costs."], ["Only the death of the main breadwinner", "An analysis that focuses only on death is not complete."], ["Only the interest rate at the end of the fixed-rate period", "Interest rate risk is relevant, but it is not an income risk such as incapacity for work or unemployment."], ["Only the value development of the home", "The value of the home is relevant for the financing, but not for the income analysis."]], "1d.2"],
["Linda (32) is permanently employed as a marketing employee and earns €3,500 gross per month. She lives with a partner and has just bought a house. After the long-term sickness of a colleague she fears loss of income if she herself becomes sick. She asks her adviser for an AOV. What does the adviser do first?", [["Establish which provisions she already has, such as wage continuation, WIA and WGA gap cover", "Only when the existing provisions are known can the adviser determine whether there is a residual income risk that justifies additional cover."], ["Immediately recommend an AOV with the shortest waiting period, so that she is covered from day one", "Without an inventory of existing cover, the advice can lead to double or unnecessary insurance."], ["Advise her to give up her permanent contract", "This is not responsible advice and does not solve the income risk."], ["Recommend a housing costs insurance instead of a thorough analysis of her income", "Recommending a housing costs insurance without analysis is also contrary to the duty of care."]], "1d.2"],
["What does the European Insurance Distribution Directive (IDD) require the distributor to do before an insurance is concluded?", [["Determine the client's demands and needs on the basis of client information", "The IDD requires that every insurance product offered matches the client's demands and needs."], ["Always have a medical examination carried out", "Whether an examination is needed depends on the product and the acceptance criteria, not on the IDD."], ["Always recommend the cheapest product on the market, regardless of the cover", "The IDD prescribes no cheapest product; it is about suitability."], ["Have the insurance approved in advance by the AFM", "The AFM does not approve individual insurances in advance."]], "1a.1"],
["Which information must an insurance distributor give the client under the IDD in any case?", [["The nature of the remuneration he receives for his services", "The IDD requires that the client knows whether the distributor receives, for example, a fee or commission."], ["The insurer's profit figures over the past ten years", "The insurer's profit figures are not mandatory client information under the IDD."], ["The adviser's personal income", "It concerns the nature of the remuneration for the service, not the private income."], ["The names of all other clients with the same product", "That would conflict with the privacy of those clients."]], "1h.5"],
["Sophie (29) is a self-employed graphic designer and makes €32,000 profit per year. She lives alone in a rented home. Her adviser recommends an AOV with own-occupation cover and the shortest waiting period, the premium of which swallows a large part of her disposable income. After a year she can no longer afford the premium. What is the main problem?", [["The advice is not suitable, because it ignores the client's financial position", "The duty of care requires that advice is also affordable; alternatives such as a longer waiting period or a lower insured amount should have been weighed up."], ["Under the Wft own-occupation cover may never be recommended to self-employed people", "Own-occupation cover can in fact be suitable; the problem is the affordability."], ["The adviser should have recommended a housing costs insurance", "That does not solve the problem of the unaffordable income cover."], ["There is no problem, as long as the client has signed the advice report and the quotation", "A signature does not release the adviser from his duty of care."]], "1a.1"],
["How should an adviser deal with a client's health declaration for an AOV or ORV application?", [["The client completes it himself; it goes directly to the medical adviser", "Health data are special categories of personal data; the adviser should not take note of the medical details."], ["The adviser completes the declaration on behalf of the client to prevent errors and delay", "In doing so the adviser takes note of sensitive data and runs the risk of incorrect statements."], ["The adviser keeps a copy in the client file", "Medical data do not belong in the advisory firm's file."], ["The declaration is shared openly via the insurer's underwriter", "Health data are assessed only by the insurer's medical department."]], "4b.2"],
["What are health data according to the GDPR (AVG)?", [["Special personal data, processing prohibited unless an exception applies", "Stricter rules apply to health data than to ordinary personal data."], ["Ordinary personal data, such as name and address, that may be freely processed", "Health data are in fact a special category."], ["Public data that the insurer may freely share with other financial institutions", "Health data are in fact highly sensitive and not public."], ["Data that fall only under the Wwft and must be destroyed after five years", "The Wwft concerns money laundering; the protection of health data falls under the GDPR."]], "1a.6"],
["Which right does a person being examined have under the Medical Examinations Act in an examination for insurance?", [["The right to hear the result first himself and to block transmission to the insurer", "With this right the examinee retains control over the result; the insurer can then refuse the application."], ["The right to determine the premium himself", "The premium is determined by the insurer."], ["The right to have the examination carried out by his own GP as examining doctor, at the insurer's expense", "A treating doctor generally may not act as examining doctor, and the examinee does not determine the costs of the examination."], ["The right to guaranteed acceptance at the standard premium after the examination", "An examination does not guarantee acceptance."]], "1a.4"],
["What is the function of the 'question limit' (vragengrens) in insurance examinations?", [["Below that limit the insurer may not ask about genetic testing and its result", "The question limit protects people with a (possible) hereditary risk who want to take out an insurance up to a certain amount."], ["Above the question limit the insurer may no longer ask the applicant any health questions at all", "It is in fact the other way round: above the limit more questions are permitted."], ["The question limit determines the maximum insured amount in an AOV", "The question limit restricts which questions may be asked, not the maximum insured amount."], ["The question limit applies only to Wwft identification", "The question limit belongs to medical examinations, not to the Wwft."]], "1h.8"],
["An installation company with twenty employees is taken over by another company through an asset transaction. There is a transfer of undertaking. What applies to the employees?", [["They transfer with their terms of employment, with an exception for pension under conditions", "On a transfer of undertaking the rights and obligations under the employment contracts pass by operation of law. The supplementary pension scheme does not transfer under conditions, for example if the acquirer has or offers its own scheme."], ["Their employment contracts end and they must apply again", "The employment contracts in fact continue with the new employer."], ["They transfer, but the new owner may immediately reduce all terms of employment", "The terms of employment transfer; the acquirer cannot unilaterally worsen them because of the transfer."], ["Only employees with a permanent contract of more than five years transfer", "All employees working in the transferred undertaking transfer, regardless of length of service."]], "1c.2"],
["A carpenter in paid employment falls from scaffolding without fall protection and becomes incapacitated for work long term. Is the employer liable for the employee's loss?", [["In principle yes, unless he demonstrates that he complied with his duty of care for safe working", "The employer is liable for loss caused by an accident at work, unless he fulfilled his duty of care or the loss is largely due to intent or deliberate recklessness of the employee."], ["Only if the employee can prove that the employer acted intentionally", "The employee does not have to prove intent; the employer must show that he exercised sufficient care."], ["Never, because the WIA and the continued payment of wages cover all loss", "Social benefits do not cover all loss, such as compensation for pain and suffering and loss of income above the benefit level."], ["Only if the employer has a liability insurance", "Liability does not depend on an insurance; an insurance at most covers the financial consequences."]], "1d.4"],
["How often must the employer and employee discuss the progress of the plan of action under the Gatekeeper Improvement Act?", [["At least once every six weeks", "The Gatekeeper Act prescribes a regular evaluation, at least once every six weeks, so that the plan is adjusted in good time if necessary."], ["Once a quarter, together with the absence report", "A quarter is too long; the law requires a more frequent evaluation of the reintegration plan."], ["Only at the first-year evaluation and the WIA application", "Those are fixed moments, but in between the progress must also be discussed periodically."], ["Every two weeks, as prescribed by the UWV", "The UWV does not prescribe a fortnightly discussion; the statutory standard is at least once every six weeks."]], "1i.9"],
["What is the first-year evaluation in long-term absence?", [["A fixed moment around week 52 to determine the reintegration objective for year two", "After about a year the employer and employee look back and record which reintegration objective is pursued in the second year."], ["An examination by the UWV that determines whether continued payment of wages continues in the second year", "The UWV only examines at the WIA application; the first-year evaluation is an arrangement between employer and employee."], ["The moment at which the prohibition on termination during sickness lapses", "The prohibition on termination applies in principle during the first two years of sickness, not only the first year."], ["The first assessment by the absenteeism insurer of whether it will pay out", "An absenteeism insurer assesses cover according to the policy; the first-year evaluation is a Gatekeeper Act step."]], "1i.9"],
["Who appoints the case manager in long-term absence?", [["The employer", "The employer is responsible for reintegration and appoints a case manager who monitors the process; this may also be the company doctor."], ["The UWV, as soon as the sickness report in week 42 has been received", "The UWV assesses the reintegration afterwards, but does not appoint a case manager."], ["The employee himself, from a list of the occupational health service", "Control lies with the employer; the employee does not choose the case manager."], ["The absenteeism insurer, as a condition for cover", "An insurer can offer help, but the statutory responsibility for appointing lies with the employer."]], "1i.9"],
["What is the reintegration report?", [["The file on the course of the reintegration that goes to the UWV with the WIA application", "With the reintegration report the employer and employee show what they have done in two years; the UWV uses it to assess their efforts."], ["A medical report of the company doctor that only the employee himself gets to see about his illness", "The report does contain the company doctor's opinion, but it is a joint file that goes to the UWV."], ["An annual report by the employer to the absenteeism insurer", "Insurers can ask for reports, but the reintegration report is a statutory document for the UWV."], ["The report of the examination by the UWV insurance physician", "The UWV examination in fact follows after the reintegration report is submitted."]], "1k.14"],
["Erik (37) works as a cook in a restaurant and earns €2,700 gross per month. He is married and has a four-year-old daughter. He is sick for four weeks with pneumonia, then works fully for three weeks and then drops out with back problems. His employer wonders whether the period for continued payment of wages starts again. How do these periods count for the continued payment of wages?", [["They are added together, because the interruption is shorter than four weeks", "Periods of sickness that follow each other with an interruption of less than four weeks are added together, regardless of the cause."], ["A new period of 104 weeks starts, because the complaints are different", "The cause is irrelevant for adding together; only the length of the interruption counts."], ["They are only added together if the company doctor establishes the same cause", "Adding together does not depend on the same cause, but on an interruption shorter than four weeks."], ["The first period lapses, because Erik was reported fully recovered", "A recovery report only breaks the chain if the employee works again for at least four weeks."]], "1i.8"],
["Gijs (52) is a production manager at a metal company and earns €4,300 gross per month. He is married and has two children who are studying. After a burn-out he has been sick for almost two years, but he is already working part of his hours again and is recovering quickly. His employer and he expect that a full return will succeed within a few months. What can they do?", [["Together ask the UWV to extend the waiting period, with wages continuing to be paid", "Employer and employee can jointly ask for a voluntary extension of the continued payment of wages, so that the WIA assessment is postponed."], ["The employer can unilaterally decide, without the employee's consent, to postpone the WIA application", "Postponement is only possible at the joint request of employer and employee; unilateral postponement is not possible."], ["The employee temporarily applies for WW until he has recovered", "A sick employee is not available for work and therefore has no right to WW."], ["Nothing, because after 104 weeks the continued payment of wages always ends", "The law in fact offers the possibility of a voluntary extension."]], "1i.9"],
["For how long must an employer continue to pay the wages of a sick employee who has already reached the AOW age?", [["A maximum of 13 weeks", "For employees who have reached the AOW age, a shorter period of continued payment of wages of a maximum of 13 weeks applies."], ["A maximum of 104 weeks, just like other employees", "For employees entitled to AOW the obligation to continue paying wages is in fact shortened."], ["Not at all, because the employee already receives AOW", "An employee entitled to AOW also has a right to continued payment of wages, only for a shorter period."], ["A maximum of 52 weeks, after which the Sickness Benefits Act takes over", "That period does not exist for those entitled to AOW; the period is shorter."]], "1g.2"],
["What may an employer ask an employee when the employee reports sick?", [["How long the absence is expected to last and where the employee can be reached", "The employer may ask what is necessary for organising the work, such as the expected duration, the address where the employee is staying and ongoing appointments."], ["What the nature and cause of the illness are, so that he can look for suitable work in a targeted way", "The diagnosis is health data; the company doctor assesses that, not the employer."], ["Which medication the employee uses and in what dose", "Medication use is medical information that the employer may not ask for or record."], ["Permission to call the GP about a medical condition", "An employer may not request medical information from the treating doctor; that goes through the company doctor."]], "1a.6"],
["Joost (34) is an account manager at a temping agency and earns €3,900 gross per month. He lives with a partner and has a baby. On his way to a client he is hit by a motorist who runs a red light and is liable for it. Joost is incapacitated for work for months and his employer continues to pay his wages. What can the employer do with the wage costs paid?", [["Recover them from the liable party and its insurer", "An employer has a right of recourse for the wages continued if a third party is liable for the incapacity for work."], ["Nothing, because continued payment of wages during sickness is always an employer risk", "Continued payment of wages is indeed his obligation, but if a third party is liable he can recover the loss."], ["Only recover if he has an absenteeism insurance", "The right of recourse does not depend on an absenteeism insurance; the insurer can recover on his behalf."], ["Reclaim the wage costs from the UWV", "The UWV does not reimburse wage costs after a traffic accident; recovery goes through the liable party."]], "1k.7"],
["What is an employer obliged to do under the Working Conditions Act (Arbowet) in guiding sick employees?", [["Be assisted by a company doctor or occupational health service under a contract", "The Arbowet obliges the employer to arrange expert support in the case of absence and to record this in a (basic) contract."], ["Take out an absenteeism insurance that covers the wages continued for all sick employees", "An absenteeism insurance is voluntary; the employer may also bear the risk himself."], ["Become a Sickness Benefits Act own-risk bearer for his flex workers", "Own-risk bearing is a choice and not an obligation under the Arbowet."], ["Also report every sickness report within a week to the UWV", "The employer only reports long-term absence to the UWV, in the 42nd week of sickness."]], "1d.1"],
["Why does a medium-sized or large employer that is publicly insured have a financial interest in few former employees flowing into the WGA and ZW?", [["Its Work Resumption Fund premium depends partly on its own inflow", "For medium-sized and large employers the Whk premium is differentiated: more inflow leads to a higher premium."], ["The UWV recovers the WGA and ZW benefits directly and in full from the last employer", "With public insurance the UWV pays the benefit; the employer notices it through the premium, not through direct recovery."], ["Otherwise he loses his right to a contract with an occupational health service", "There is no sanction that links the occupational health contract to the inflow into the WGA or ZW."], ["Otherwise the AFM imposes a fine on him for poor absence policy", "The AFM supervises the financial markets, not the absence policy of employers."]], "1d.1"],
["What can an employer do if a sick employee does not comply with reasonable control instructions, such as not appearing at the company doctor's consultation?", [["Suspend the wages until the employee complies after all", "If reasonable control instructions are not complied with, the employer may suspend the wages; after compliance they are paid after all."], ["Dismiss the employee summarily", "Summary dismissal is a heavy measure; not following control instructions in the first instance leads to suspension."], ["Stop the wages permanently for the entire remaining period of sickness", "Suspending is something different from stopping: with suspension the employee receives the wages later after all."], ["Ask the UWV to withhold the Sickness Benefits Act benefit", "An employee in employment receives wages from the employer, not a ZW benefit; the UWV is not the one to act here."]], "1k.5"],
["How high is a Sickness Benefits Act benefit as a rule?", [["70% of the (capped) daily wage", "The standard ZW benefit amounts to 70% of the daily wage, which is subject to a maximum."], ["100% of the wage in the first year of sickness", "100% applies only in special situations, such as sickness due to pregnancy; the general rule is 70%."], ["75% for the first two months, then 70%", "That build-up applies to the WW and the wage-related WGA, not the Sickness Benefits Act."], ["A fixed percentage of the minimum wage", "The ZW benefit is wage-related and based on the person's own daily wage."]], "1i.2"],
["Anouk (30) is a legal assistant at a notary's office and earns €3,200 gross per month. She is married and is expecting her first child. Three months before her pregnancy leave she becomes sick due to severe pregnancy complaints. Her employer wants to know which costs he must bear. What is her employer's position?", [["He continues to pay the wages and can apply to the UWV for a ZW benefit for her", "With sickness due to pregnancy a safety net applies: the employer continues to pay and receives a ZW benefit from the UWV as compensation."], ["He does not have to pay wages, because pregnancy is not an illness", "Sickness as a result of pregnancy is sickness; the employer must continue to pay the wages."], ["Her pregnancy leave starts immediately on the sickness report, regardless of the due date", "The leave starts around a fixed period before the due date, not automatically on sickness."], ["He bears the wage costs entirely himself, without any compensation", "In fact, to spare employers, the ZW safety-net scheme applies to pregnancy-related sickness."]], "1b.5"],
["Who provides the benefit during an employee's pregnancy and maternity leave?", [["The UWV, under the Work and Care Act (WAZO); often paid via the employer", "The WAZO benefit comes from the UWV; the employer usually applies for it and continues to pay it via the wages."], ["The employer, without being compensated for it", "The employer often pays out, but receives the benefit from the UWV for it."], ["The Social Insurance Bank, because the leave pay falls under the national insurances", "The SVB administers the national insurances; the leave pay is an employee scheme through the UWV."], ["The health insurer, as part of maternity care", "The health insurer reimburses care, not income during leave."]], "1b.5"],
["What does the no-risk policy (no-riskpolis) mean?", [["On sickness of an employee with a work disability the employer receives ZW", "The no-risk policy reduces the risk of hiring someone with a work disability: on sickness the UWV compensates the wage costs."], ["An absenteeism insurance without excess, specially developed for small employers", "The no-risk policy is a public scheme of the UWV and not a private absenteeism insurance."], ["Extra protection against dismissal for employees with a chronic illness", "The scheme gives no protection against dismissal, but wage cost compensation for the employer."], ["A premium-free AOV for young disabled people who start a business", "A no-risk policy concerns employees in an employment relationship, not an AOV for entrepreneurs."]], "1b.6"],
["Sven (45) is a project leader at an engineering firm and earns €4,800 gross per month. He is married and has three children. He donates a kidney to his brother and is sick for six weeks after the operation. His employer asks whether he must bear those wage costs himself. What applies?", [["The employer continues to pay and can receive ZW via the UWV", "For sickness due to organ donation a safety-net scheme in the Sickness Benefits Act applies; the employer receives compensation."], ["Sven has no right to wages, because he voluntarily chose the operation", "With organ donation too there is sickness for which wages are continued."], ["Sven immediately receives a WIA benefit for the recovery period", "The WIA only comes into play after a waiting period of 104 weeks, not for short-term absence."], ["The brother's health insurer reimburses Sven's wages", "The health insurer reimburses the medical costs, not the donor's wages."]], "1b.5"],
["Ingrid (54) was a team leader at a call centre and earned €3,200 gross per month. She is single. After a reorganisation she has received a WW benefit for two months. Then she becomes sick and has to undergo long-term treatment. What happens to her benefit?", [["The WW continues for the first 13 weeks; after that she can receive a ZW benefit", "With sickness during the WW, the WW is still paid for 13 weeks; if the sickness lasts longer, the Sickness Benefits Act follows."], ["The WW stops immediately and the Sickness Benefits Act starts from the first day", "First there is a period in which the WW continues; only after that does the ZW follow."], ["She no longer has a benefit, because she is not available", "There is in fact a scheme: first WW, then ZW."], ["The WW simply continues for the full remaining duration, regardless of how long the sickness lasts", "After 13 weeks of sickness the WW stops and she moves to the Sickness Benefits Act."]], "1i.2"],
["Who submits the WIA application?", [["The employee, together with the reintegration report", "The employee applies for the WIA; the reintegration report that he draws up with the employer belongs with the application."], ["The employer, without involvement of the employee", "The employer supplies its part of the report, but the application itself is made by the employee."], ["The company doctor, as soon as the waiting period is almost over", "The company doctor gives medical advice, but does not submit a benefit application."], ["Nobody; the UWV starts the assessment automatically", "The UWV sends information, but without an application from the employee no assessment follows."]], "1k.1"],
["What division of roles applies in the WIA assessment by the UWV?", [["The insurance physician determines the limitations; the labour expert calculates the loss of earning capacity", "First the insurance physician determines what someone can still do medically; then the labour expert looks for suitable jobs and calculates the degree of incapacity for work."], ["The labour expert determines the limitations; the insurance physician calculates the degree of incapacity for work", "The roles are reversed here: the medical assessment belongs to the insurance physician."], ["The employer's company doctor determines the percentage and the UWV adopts it", "The UWV assesses independently; the company doctor has no decisive role in it."], ["Both only advise; the employer takes the decision", "The decision on the WIA is taken by the UWV, not by the employer."]], "1k.2"],
["What does 'permanent' incapacity for work mean for the IVA?", [["There is no, or only a slight, chance of recovery", "For the IVA someone must be not only fully but also permanently incapacitated for work: recovery is not, or hardly, to be expected."], ["The employee has already been sick for at least two years", "Two years of sickness is the waiting period for the WIA and says nothing yet about the chance of recovery."], ["The employee is at least 80% incapacitated for work", "80% or more means fully incapacitated for work; permanence is a separate condition."], ["The sickness is expected to last at least another year", "Permanence concerns the absence of recovery in the long term, not a period of a year."]], "1i.11"],
["Youssef (36) worked as a self-employed IT consultant when he took out an AOV with a premium for office work. He is married and has a four-year-old son. A year ago he switched to work as a self-employed roofer, from which he makes €50,000 profit per year, but he did not report that change of occupation to the insurer. After a fall from a roof he reports himself incapacitated for work. What can the insurer generally do?", [["Reduce the benefit proportionally to premium paid versus correct premium", "AOV conditions usually provide for a proportional reduction of the benefit in the case of an unreported change of occupation, because too little premium was paid for the actual risk."], ["Pay out in full, because the change of occupation has nothing to do with the claim", "The change of occupation in fact increases the risk; the too-low premium has consequences for the benefit."], ["Refer Youssef to the UWV for a WIA benefit", "As a self-employed person, Youssef is not insured for the WIA."], ["Increase the benefit, because roofing is a heavier occupation", "A heavier occupation leads to a higher premium, not to a higher benefit if that premium has not been paid."]], "1f.7"],
["How high is the wage-related WGA benefit for someone who does not work?", [["75% of the daily wage for the first two months, then 70%", "In the wage-related phase the beneficiary first receives 75% and after two months 70% of the (capped) daily wage."], ["75% of the daily wage during the entire wage-related phase", "75% applies only for the first two months; after that it drops to 70%."], ["A percentage of the minimum wage, depending on the degree of incapacity", "That is the system of the follow-up benefit, not of the wage-related phase."], ["100% of the maatmaninkomen up to the maximum daily wage", "The WGA does not provide full replacement of income."]], "1i.12"],
["How is the WGA wage supplement benefit calculated?", [["70% of the difference between maatmaninkomen and residual earning capacity", "The wage supplement tops up on the basis of what someone could theoretically still earn, not on the basis of what he actually earns."], ["70% of the full maatmaninkomen", "The benefit replaces only part of the loss, not the entire former income."], ["70% of the difference between the maatmaninkomen and the wage actually earned", "For the wage supplement the residual earning capacity counts, not the wage actually earned."], ["A fixed percentage of the minimum wage", "A benefit based on the minimum wage is the follow-up benefit, not the wage supplement."]], "1i.12"],
["Wim (49) is a lorry driver and earned €3,000 gross per month. He is married and has two teenagers. After two years of sickness due to a back condition he received no WIA, because he was 30% incapacitated for work; since then he has worked as a planner. Three years later his back deteriorates due to the same condition and he is 50% incapacitated for work. What applies?", [["He can still receive WIA: it happens within five years and due to the same cause", "A 35-minner can still receive WIA if, within five years after the waiting period, he becomes at least 35% incapacitated for work due to the same cause."], ["He no longer has any right to WIA, because he was already definitively rejected after the waiting period", "An earlier rejection does not rule out later entitlement; the law in fact has a provision for an increase due to the same cause."], ["He must first go through a new waiting period of 104 weeks", "For an increase due to the same cause within the period, no new full waiting period applies."], ["He can only receive an IVA benefit", "At 50% incapacity for work the WGA comes into play, not the IVA."]], "1d.5"],
["What can an employee do if he disagrees with the UWV's WIA decision?", [["Lodge an objection with the UWV within six weeks", "Against a UWV decision an objection with the UWV itself is open; the period is six weeks."], ["Lodge a complaint with Kifid within two weeks", "Kifid handles disputes with financial service providers, not with the UWV."], ["Go directly to the Supreme Court within six months", "First an objection follows and then, if necessary, an appeal to the district court."], ["Submit a request to the National Ombudsman within a year", "The ombudsman handles complaints about conduct, not the substance of a benefit decision."]], "1k.5"],
["Does the partner's income or assets play a role in the level of a WIA benefit?", [["No, the WIA has no partner or means test", "The WIA benefit depends on the person's own daily wage and the degree of incapacity for work, not on the household."], ["Yes, the household's assets above an exemption are deducted", "A means test applies in, for example, social assistance, not the WIA."], ["Yes, the partner's income is offset in full", "Offsetting against partner income belongs to the Supplementary Benefits Act and social assistance, not the WIA itself."], ["Only in the follow-up phase is the partner's income counted", "In the follow-up phase too, the partner's income plays no role for the WIA."]], "1k.10"],
["What does the Supplementary Benefits Act (Toeslagenwet) do?", [["Tops up a benefit to the social minimum, considering the partner's income", "A supplement is possible if the benefit is below the social minimum; the partner's income is taken into account."], ["Tops up an employee benefit to the level of the employee's last-earned wage", "The Supplementary Benefits Act tops up to the social minimum, not to the previous wage."], ["Provides rent allowance and healthcare allowance to people with a benefit", "Rent and healthcare allowance fall under the Awir (General Act on Income-related Schemes) and the Benefits Service, not the Supplementary Benefits Act."], ["Gives a supplement only to single people with a low benefit", "Married and cohabiting people can also receive a supplement, depending on the partner's income."]], "1i.2"],
["Where can a young disabled person with earning capacity generally turn for support since 2015?", [["To the municipality, under the Participation Act", "Since 2015, young people with earning capacity no longer enter the Wajong; the municipality supports them through the Participation Act."], ["To the UWV, which gives them a full Wajong benefit", "Since 2015 the Wajong is only for those who permanently have no earning capacity."], ["To the SVB, which pays them a youth benefit", "The SVB administers national insurances and has no role for young disabled people with earning capacity."], ["To the health insurer, through the Long-term Care Act (Wlz)", "The Wlz regulates care, not income or work support."]], "1i.2"],
["What is a starting point of the Wajong Simplification Act (Wet vereenvoudiging Wajong)?", [["Working must pay: anyone who earns more alongside the Wajong is better off overall", "The simplification ensures that Wajong recipients with work always keep more than without work."], ["The Wajong benefit stops as soon as someone accepts paid work", "Working alongside the Wajong remains possible; the benefit is offset, not ended."], ["The Wajong is paid out once as a fixed lump sum", "The Wajong is a periodic benefit and not a one-off lump sum."], ["The partner's income is henceforth offset against the Wajong benefit, as in social assistance", "The Wajong has no partner test; that act did not introduce one."]], "1i.2"],
["Daan (17) is at secondary vocational school and lives with his parents, who together earn €5,000 gross per month. He has never worked in paid employment, not even a side job. He is seriously injured in a traffic accident. The UWV determines that he permanently has no earning capacity. Which scheme comes into play first?", [["The Wajong, because he became incapacitated for work before turning 18", "Daan was not an insured employee and therefore cannot receive WIA; as a young disabled person he can apply for the Wajong."], ["The WIA, after a waiting period of 104 weeks", "The WIA is only for employees who were insured; Daan has never worked."], ["The Sickness Benefits Act, because he has no employer who pays wages", "The ZW is an employee insurance for those previously insured; Daan does not fall under it."], ["The Anw, because his parents have to care for him", "The Anw is a surviving dependants' scheme and has nothing to do with incapacity for work."]], "1i.2"],
["How high is the WW benefit?", [["75% of the daily wage for the first two months, then 70%", "The WW starts at 75% of the (capped) daily wage and drops to 70% after two months."], ["Always 70% of the last-earned gross wage, without a maximum", "The daily wage is capped and a higher percentage applies for the first two months."], ["A fixed amount at the level of the social minimum", "The WW is wage-related; a top-up to the minimum goes through the Supplementary Benefits Act."], ["100% in the first month, then 70% of the daily wage", "The WW has no full continued payment in the first month."]], "1i.2"],
["What is the maximum duration of a WW benefit?", [["24 months", "Since the shortening of the WW the maximum duration is 24 months, with a long employment history."], ["38 months", "38 months was the old maximum duration; it has been reduced step by step."], ["12 months", "12 months is too short; with a long employment history the duration is longer."], ["Unlimited, until the AOW age", "The WW is a temporary benefit with a maximum duration."]], "1i.2"],
["Lars (26) worked for a year and a half as a junior consultant after his studies for €3,200 gross per month. He lives with his girlfriend. His temporary contract is not extended and he applies for WW. He meets the weeks requirement, but not the years requirement. For how long does he receive WW?", [["Three months", "Anyone who only meets the weeks requirement receives a short WW benefit of three months."], ["No WW, because both requirements must be met", "For the basic entitlement the weeks requirement suffices; the years requirement only determines whether the duration becomes longer."], ["Six months, regardless of his employment history", "A fixed duration of six months does not exist for this situation."], ["One month per year worked, with a minimum of a year", "A duration per year worked requires that the years requirement is also met."]], "1i.2"],
["What does the years requirement (jareneis) in the WW mean?", [["In four of the five preceding calendar years, at least 208 hours of wages in each", "Anyone who meets the years requirement receives a WW duration that depends on their employment history, instead of only three months."], ["Having worked at least 26 weeks in the last 36 weeks", "That is the weeks requirement (referte-eis), not the years requirement."], ["Having been employed by the same employer for at least five years without interruption", "The years requirement does not require employment with one employer."], ["Having worked full-time in paid employment in each of the last four calendar years", "Working full-time is not a requirement; it concerns a minimum number of hours with wages per year."]], "1i.2"],
["Which obligation does someone with a WW benefit have in any case?", [["Actively look for work and pass on his job applications to the UWV", "A WW beneficiary must make an effort to find work and be able to show that he is applying."], ["Accept only work at his own level throughout the entire WW", "What counts as suitable work becomes broader the longer the WW lasts."], ["Report his assets to the UWV every year", "The WW has no means test; assets play no role."], ["Make sure that his partner is also registered as a job seeker", "The obligations apply to the beneficiary himself, not to his partner."]], "1k.5"],
["What happens to the concept of 'suitable work' the longer the WW lasts?", [["It becomes broader: lower-paid work or work at a lower level is also suitable", "The WW beneficiary must gradually widen his search area; after some time almost all work is suitable."], ["It stays the same: throughout the entire WW only work at his own educational level is suitable", "The concept in fact broadens over time."], ["It becomes narrower: only work with the previous employer is suitable", "There is no restriction to the previous employer."], ["It no longer plays a role after the first three months", "Suitable work remains relevant throughout the entire WW."]], "1k.5"],
["Saskia (46) is an HR adviser and earns €4,100 gross per month. She is married and has a ten-year-old son. After a conflict she concludes, at her employer's initiative, a settlement agreement that ends her employment with immediate effect. Her notice period would have been two months. What is the consequence for her WW?", [["Her WW only starts after the fictitious notice period", "If the notice period is not observed, the UWV moves the WW start date back by that period."], ["She receives no WW, because she agreed herself", "WW entitlement can exist with a settlement agreement; her agreement does not make her culpably unemployed."], ["Her WW starts immediately and is extended by two months", "The notice period does not extend the WW; the start date is moved back."], ["The employer must repay her WW for two months to the UWV", "The UWV recovers nothing from the employer; the employee receives WW later."]], "1i.2"],
["Under what condition can an employee receive WW after termination by a settlement agreement?", [["The initiative lies with the employer and there is no urgent reason for dismissal", "A settlement agreement does not rule out WW, provided the employee is not culpably unemployed: the initiative comes from the employer and there is no urgent reason."], ["The employee himself asked for the employment to be terminated, in order to start elsewhere", "Anyone who asks for dismissal themselves without urgent reason is culpably unemployed."], ["The agreement has been approved in advance by the subdistrict court judge", "A settlement agreement does not need to be approved by a judge."], ["The employee waives his right to a transition payment", "Waiving the transition payment is not a condition for WW."]], "1i.2"],
["Wendy (51) worked for twenty years as an administrator at a printing company and earned €3,300 gross per month. She is married and her children live independently. She is dismissed for business-economic reasons and receives a transition payment. She then applies for WW. What is the influence of the payment on her WW?", [["None; the transition payment is not offset", "The transition payment is compensation for dismissal and is not deducted from the WW."], ["The WW is reduced by the full amount of the payment", "There is no offsetting; the WW is not reduced."], ["The WW only starts once the payment has been used up", "That rule does not exist; the WW starts independently of the transition payment."], ["The WW duration becomes shorter the higher the payment", "The duration depends on the employment history, not on the amount of the payment."]], "1i.2"],
["Bas (37) is a freelancer (zzp'er) web developer and made €55,000 profit last year. He is married and has two young children. His main client ends the cooperation and Bas has hardly any turnover for months. He is not sick, but his income largely falls away. What can he rely on?", [["Not the WW; possibly Bbz social assistance via the municipality", "A self-employed person is not insured for the WW; the municipality can offer support under conditions."], ["A WW benefit calculated on the basis of his average profit of the past years", "The WW applies only to employees; profit from business gives no WW entitlement."], ["A ZW benefit, because he has no employer", "The ZW is for sick employees without an employer, not for entrepreneurs without assignments."], ["His AOV, because it also covers loss of turnover", "An AOV covers loss of income due to incapacity for work, not due to a lack of assignments."]], "1i.7"],
["What is a characteristic of the IOW compared with social assistance?", [["The assets and the partner's income do not count", "The IOW is a follow-up benefit for older unemployed people without a means test or partner test, unlike social assistance."], ["The person's own assets are tested in full", "A means test applies to social assistance and not to the IOW."], ["The benefit is provided by the municipality", "The IOW is administered by the UWV."], ["The benefit is always a loan that must be repaid", "The IOW is an ordinary benefit and not a loan."]], "1i.2"],
["Maarten (58) was a buyer at a retail chain and earned €3,700 gross per month. He is single and lives in an owned home with considerable equity. After his dismissal he found no new job and his WW has now ended. He applies for social assistance. What must he take into account?", [["Because of the assets in his home, social assistance may be provided as a loan", "Social assistance has a means test; with assets in the owner-occupied home above the limit, the municipality may provide assistance as a loan."], ["He must first sell the home and use up the equity before he can receive social assistance", "Sale is not required; the municipality can give assistance in the form of a loan."], ["The equity plays no role, only the savings count", "Assets in the owner-occupied home are also included in the means test."], ["He receives an IOW benefit, because he owns a home", "Owning a home gives no right to IOW; that depends on age and the WW situation."]], "1i.2"],
["Wouter (43) was a salesman at a car dealership and earned €3,400 gross per month. He is married and has three children. Since January he has received WW and this year he has not worked. He asks whether he gets the employed person's tax credit (arbeidskorting) on his WW benefit. What is correct?", [["No, the employed person's tax credit applies only to work income", "The employed person's tax credit is a tax credit for people who work; a benefit does not count for it."], ["Yes, the WW is treated as wages for the employed person's tax credit", "The WW is not employment income for the employed person's tax credit."], ["Yes, but only in the first two months of the WW", "There is no temporary employed person's tax credit on WW."], ["Only if he also has a part-time job, on the total", "Even then the employed person's tax credit applies only to employment income and not to the WW."]], "1i.5"],
["What is the position within social security of a self-employed person without staff (zzp'er) who counts as an entrepreneur for income tax?", [["He is not insured for the employee insurances, but is for the national insurances", "A zzp'er falls outside the ZW, WIA and WW, but as a resident of the Netherlands is insured for national insurances such as AOW and Anw."], ["Like an employee, he is compulsorily insured for ZW, WIA and WW", "Employee insurances apply to those working in an employment relationship, not to an entrepreneur."], ["He is not insured for any social insurance", "For the national insurances, such as the AOW, a zzp'er living in the Netherlands is insured."], ["He is only insured for the WW, because he can lose assignments", "A zzp'er is not insured for the WW; if assignments fall away there is no WW benefit."]], "1a.8"],
["Which condition must in any case apply to the deceased for an Anw benefit to the surviving dependant?", [["The deceased was Anw-insured, for example by living or working in the Netherlands", "The Anw is a national insurance: the deceased must have been insured at the time of death."], ["The deceased had paid Anw premium through his wages for at least ten years", "There is no minimum premium period; being insured at the time of death is decisive."], ["The deceased had a supplementary Anw gap insurance", "A gap insurance is private and not a condition for the statutory Anw."], ["The deceased was employed by an employer established in the Netherlands at the time of death", "Someone who was not employed, such as a self-employed person, can also be insured as a resident."]], "1i.2"],
["Case: Tim and Rosa live together unmarried and run a joint household. They have a five-year-old son. Tim dies. Can Rosa receive an Anw benefit?", [["Yes, unmarried cohabitants with a joint household also count as partners", "The Anw looks at the joint household; with a child under 18, Rosa may be entitled, subject to the income test."], ["No, only married people and registered partners are entitled to an Anw surviving dependants' benefit", "Unmarried cohabitants can also count as partners under the Anw."], ["No, because they have no cohabitation agreement", "A cohabitation agreement is not required; it is about the actual joint household."], ["Only their son is entitled, to an orphan's benefit", "An orphan's benefit is for children whose parents have both died; Rosa is still alive."]], "1i.2"],
["Which kind of income or assets plays NO role in the level of an Anw surviving dependants' benefit?", [["The surviving dependant's assets, such as savings", "The Anw has an income test, but no means test: savings have no influence."], ["Wages from a job of the surviving dependant", "Income from work is partly offset against the Anw."], ["A WIA benefit of the surviving dependant", "Benefits connected with work, such as the WIA, are offset against the Anw."], ["Profit from business that the surviving dependant makes themselves", "Profit is also income from work that is offset against the Anw."]], "1i.2"],
["Petra (47) is a part-time receptionist and earns €1,400 gross per month. Her husband died five years ago and since then she has received an Anw benefit because she cares for their daughter. Her daughter will soon turn 18. Petra is not incapacitated for work. What happens?", [["The Anw benefit stops", "The right to Anw is linked to caring for a child under 18; without another ground the benefit ends."], ["The benefit continues until Petra reaches the AOW age", "Continuing until the AOW age is only possible if she meets another condition, such as incapacity for work."], ["The benefit continues for as long as the daughter studies", "A child's studies do not extend the surviving dependants' benefit."], ["The benefit is converted into an orphan's benefit for the daughter", "An orphan's benefit applies only if both parents have died."]], "1i.2"],
["Case: Gerard (52) loses his wife. They have no children. Gerard is 50% incapacitated for work. Can he receive an Anw benefit?", [["Yes, with at least 45% incapacity for work, depending on income", "In addition to caring for a child under 18, incapacity for work of at least 45% also gives access to the Anw."], ["No, without children under 18 a widower is never entitled to Anw", "Incapacity for work is an independent ground for the Anw."], ["No, the Anw is intended only for widows", "The Anw makes no distinction between men and women."], ["Yes, but only when he is 60", "An age limit of 60 does not exist in the Anw."]], "1i.2"],
["How is an Anw benefit treated for tax purposes?", [["As taxable income in box 1; the SVB withholds payroll tax", "The Anw is a public benefit that is taxed as income."], ["As an untaxed benefit, like an ORV benefit", "An ORV lump sum does not fall in box 1, but the Anw is taxed."], ["As assets in box 3 at the reference date", "A periodic Anw benefit is income, not box 3 assets."], ["Under inheritance tax, because the benefit arises from death", "The Anw is a social benefit and does not fall under inheritance tax."]], "1i.5"],
["Why is it sensible to align the end age of an AOV with the AOW age?", [["Because the AOW only starts then and the income gap until that moment must be covered", "If the AOV stops earlier, a period without income on incapacity for work arises between the end age and the AOW age."], ["Because the premium only then becomes tax-deductible", "The deductibility of the premium does not depend on the end age."], ["Because an AOV must by law always run until the AOW age", "There is no legal obligation; a lower end age is possible, but risky."], ["Because otherwise the insurer may not apply a waiting period", "The waiting period is independent of the end age."]], "1g.8"],
["What does indexation of an AOV benefit mean?", [["The benefit rises during incapacity for work by a fixed percentage or with inflation", "Indexation protects against loss of purchasing power during long-term incapacity for work."], ["The insured amount is automatically reduced every year as the insured gets older and the risk rises", "That is not indexation but a reduction; indexation in fact raises."], ["The premium is adjusted annually to the insurer's claims experience", "That concerns a premium adjustment, not indexation of the benefit."], ["The waiting period automatically becomes shorter the longer the insured has been insured", "Indexation has nothing to do with the waiting period."]], "1g.5"],
["Merel (31) is a freelancer (zzp'er) communications adviser and makes €50,000 profit per year. She lives with a partner and has a one-year-old son. To save premium she chooses an AOV with a benefit period of a maximum of five years per claim. Her adviser wants to point out the risk of that. What is the main drawback?", [["In long-term incapacity the benefit stops, while her loss of income continues", "A limited benefit period lowers the premium, but leaves the risk of permanent incapacity for work largely uninsured."], ["The premium is higher than for a comparable benefit that runs until the end age", "A shorter benefit period in fact leads to a lower premium."], ["The benefit is not taxed, but the premium is not deductible either", "The benefit period changes nothing about the tax treatment."], ["She receives no benefit in the case of partial incapacity for work", "Whether partial incapacity for work is covered depends on the threshold, not on the benefit period."]], "1g.8"],
["What does the 'suitable work' criterion in an AOV mean?", [["He is incapacitated if he cannot do work that fits his education and experience", "Suitable work lies, in scope, between own-occupation incapacity and generally accepted work."], ["He is only incapacitated if he can no longer do any generally accepted job in the labour market", "That resembles the generally accepted work criterion, the narrowest criterion."], ["He is incapacitated if he can no longer practise his own occupation", "That is own-occupation incapacity, the broadest criterion."], ["The insured decides for himself which work is suitable for him", "The judgement lies with the insurer on the basis of objective standards, not with the insured."]], "1g.16"],
["What does the duty of disclosure mean when taking out an AOV?", [["The client must disclose relevant facts he knows or ought to know, in advance", "This pre-contractual duty follows from the Dutch Civil Code (BW) and applies to all facts that may influence the assessment of the risk."], ["The insurer must explain all policy conditions to the client in detail in advance", "The insurer does have information duties, but the duty of disclosure rests on the policyholder."], ["The insured must report every sickness to the insurer within 24 hours during the term", "That is a duty in the case of loss during the term, not the duty of disclosure before concluding."], ["The adviser must pass on the client's medical data", "The client provides his health data himself, directly to the medical adviser."]], "1a.2"],
["Hugo (44) is a self-employed plasterer and makes €48,000 profit per year. He is married and has two children. When applying for his AOV he deliberately concealed on the health declaration his years of back complaints and physiotherapy to prevent an exclusion. After three years he reports himself incapacitated for work because of his back. What can the insurer do?", [["Refuse a benefit and cancel the insurance, because Hugo deliberately concealed", "With intent to mislead, the right to a benefit lapses and the insurer can terminate the agreement."], ["Nothing, because after two years the insurer can no longer rely on non-disclosure", "There is no two-year limitation period that covers intentional non-disclosure."], ["Only raise the premium retroactively and pay out in full", "In the case of intent the insurer does not have to pay out; a premium correction applies in the case of unintentional non-disclosure."], ["Refer Hugo to the UWV for a WIA benefit", "A self-employed person is not insured for the WIA, so that way out does not exist."]], "1a.2"],
["Karin (39) is a self-employed physiotherapist and makes €58,000 profit per year. She is married and has a six-year-old daughter. Her AOV has a threshold of 25% and pays out pro rata to the degree of incapacity for work. After a serious herniated neck disc the insurer determines that she is 60% incapacitated for work. What does she receive in principle?", [["A benefit that corresponds to 60% incapacity for work, not the full amount", "With pro rata payment the insured receives a part of the insured amount that corresponds to the degree of incapacity for work."], ["The full insured amount, because she is well above the policy threshold of 25%", "Paying out above the threshold does not automatically mean a full benefit."], ["Nothing, because she is not fully incapacitated for work", "The 25% threshold has been reached, so she is entitled to a benefit."], ["A benefit of 25% of the insured amount", "The threshold determines when a benefit is paid, not how much."]], "1g.3"],
["What is the ZEZ benefit (Zelfstandig en Zwanger, self-employed and pregnant)?", [["A UWV benefit for the self-employed around pregnancy and childbirth", "Self-employed people can also receive a benefit via the UWV during pregnancy and maternity leave."], ["An AOV cover that insurers are obliged to offer", "The ZEZ is a public scheme and not a mandatory AOV cover."], ["A municipal loan for pregnant entrepreneurs", "The ZEZ is not a loan and is not provided by the municipality."], ["An income tax exemption during the leave", "The ZEZ is a benefit and not a tax exemption; the benefit is taxed."]], "1i.6"],
["Esther (35) worked for ten years as a laboratory technician in paid employment for €3,300 gross per month. She is single and next month will continue as a self-employed trainer. Because of a history of migraines she expects that a private AOV will be difficult or expensive. She asks which alternatives there are. Which option can an adviser discuss with her besides a private AOV?", [["Under conditions and within a limited period, a voluntary insurance with the UWV", "Anyone who loses the compulsory employee insurance can, under conditions, insure voluntarily with the UWV, for example for the WIA."], ["Retain her right to WIA without further action, because she paid premium as an employee for ten years", "Compulsory insurance ends at the end of the employment relationship; years built up give no lasting cover."], ["Apply for a WW benefit as a supplement in her start-up year", "Anyone who voluntarily stops being an employee to start for themselves is not unemployed within the meaning of the WW."], ["A Wajong benefit, because she is starting a new occupation", "The Wajong applies to those who became incapacitated for work at a young age."]], "1i.4"],
["What does premium waiver on incapacity for work in an AOV mean?", [["During incapacity for work the insured does not have to pay (pro rata) premium", "Premium waiver prevents the insured from having to keep paying premium while missing income due to incapacity for work."], ["The premium is refunded in full after the waiting period", "No refund takes place; the premium lapses during the incapacity for work."], ["The premium is tax-exempt and therefore not deductible", "Premium waiver is a policy condition, not a tax rule."], ["The insured does not have to pay premium in the first year after the start", "A premium-free start year has nothing to do with premium waiver on incapacity for work."]], "1g.9"],
["What is the main difference between an accident insurance and an AOV?", [["An accident insurance pays out only after an accident, not sickness", "An accident insurance pays a benefit on permanent disability or death due to an accident; sickness, the most common cause of incapacity for work, falls outside it."], ["An accident insurance also covers loss of income due to sickness", "Sickness in fact falls outside an accident insurance."], ["An AOV only pays out in the event of an accident at work", "An AOV covers incapacity for work due to sickness and accident."], ["An accident insurance gives a monthly income for life after an accident", "An accident insurance usually pays a one-off amount."]], "1f.1"],
["Which risk does a WIA 35-minus insurance (also called WIA floor insurance) cover?", [["The loss of income of an employee who is declared less than 35% incapacitated for work", "A 35-minner receives no WIA; this insurance tops up the loss of income that thereby remains uninsured."], ["The wage above the maximum daily wage in case of full incapacity for work", "That is the domain of the WIA excess insurance."], ["The gap in the WGA follow-up phase if the residual earning capacity is insufficiently used", "That gap is covered by the WGA gap insurance."], ["The employer's continued payment of wages in the first two years of sickness", "That employer risk is covered by an absenteeism insurance."]], "1g.13"],
["How is a premium for a collective WGA gap insurance that the employer withholds from the employee's gross wage treated for tax purposes?", [["The premium reduces the taxable wage; the later benefit is taxed", "The reversal rule applies to this income insurance: deduction or withholding up front and tax on the benefit."], ["The premium is not deductible and the benefit is untaxed", "That treatment belongs to, for example, a housing costs insurance, not to a WGA gap insurance."], ["The premium is deductible and the benefit is also untaxed", "Deduction of the premium and an untaxed benefit do not go together for tax purposes; the reversal rule applies."], ["The premium falls in box 3 and the benefit under inheritance tax", "Box 3 and inheritance tax play no role in this incapacity cover."]], "1i.10"],
["When does a WIA excess insurance generally pay out?", [["When he is entitled to WIA and earned above the maximum daily wage", "The excess insurance builds on the WIA assessment and covers the part of the wage above the maximum daily wage."], ["From the first day of sickness, alongside the employer's continued payment of wages", "In the first two years the employer continues to pay wages; the excess cover follows on from the WIA."], ["Only if the employee ends up in the IVA", "The excess insurance can also pay out with a WGA benefit."], ["Also if the employee is less than 35% incapacitated for work", "A separate cover exists for 35-minners; the excess insurance generally follows the WIA."]], "1g.13"],
["Who has the interest in an insurance of WGA own-risk bearing?", [["The employer, who as own-risk bearer bears WGA costs of (ex-)employees", "An own-risk bearer pays the WGA benefits itself; with this insurance it covers that financial risk."], ["The employee, who thereby covers the gap in the follow-up phase", "The gap for the employee is covered by the WGA gap insurance, not the own-risk bearer insurance."], ["The UWV, which thereby limits its own WGA benefit costs for large employers", "With own-risk bearing the employer pays, not the UWV; the UWV is not a policyholder."], ["The absenteeism insurer, which thereby reinsures its own risk", "Reinsurance by an insurer is something different from an own-risk bearer insurance for the employer."]], "1i.13"],
["Rachid (38) is a work planner at a contractor and earns €3,800 gross per month. He is married and has two children. Through his employer he is insured with a collective WGA gap insurance. He is offered a job at a smaller employer. What is the main point of attention?", [["Check whether the new employer offers comparable cover", "A collective insurance applies to employees of that employer; on leaving, a gap in cover may arise."], ["Nothing, because the collective cover automatically goes along to the next employer", "A collective policy belongs to the employer; that cover does not automatically go along."], ["Convert the cover into a housing costs insurance", "A housing costs insurance is temporary and covers only housing costs; that is not an equivalent replacement."], ["Apply for a WW benefit for the period without cover", "A gap in cover on changing jobs gives no right to WW."]], "1j.3"],
["What is the excess period (eigenrisicoperiode) in an absenteeism insurance?", [["The first period of absence in which the employer bears the wages itself", "An excess period, expressed in days or weeks, lowers the premium but leaves short-term absence at the employer's expense."], ["The period after the sickness report in which the employee receives no wages", "That concerns waiting days for the employee, not the employer's excess under the policy."], ["The period in which the insurer only reimburses the employer's reintegration costs", "During the excess period the insurer in fact reimburses no wages."], ["The period after two years of sickness in which the WIA starts", "After two years the continued payment of wages ends; that is separate from the excess in the absenteeism policy."]], "1g.10"],
["Why do employers with an absenteeism insurance often opt for a surcharge on the insured wage?", [["To also cover employer costs such as social premiums, pension premium and holiday pay", "In the case of sickness, other wage costs continue besides the gross wage; with a surcharge the employer also insures these."], ["To also insure the UWV wage sanction for insufficient reintegration", "A surcharge covers wage costs in ordinary absence; a wage sanction is usually excluded."], ["To let the employee receive more than his own wage", "The benefit goes to the employer; the employee receives the wage he is entitled to."], ["Because the law prescribes a minimum surcharge on the insured sum", "An absenteeism insurance is voluntary and has no statutory surcharge."]], "1g.10"],
["Is a UWV wage sanction generally covered by an absenteeism insurance?", [["No, a wage sanction for insufficient reintegration is generally excluded", "A wage sanction is a consequence of the employer's own shortcomings; insurers generally do not cover it."], ["Yes, all wage costs of sick employees are fully covered", "A wage sanction is not an ordinary absence risk but a sanction; it generally falls outside the cover."], ["Yes, but only if the employer is also an own-risk bearer for the WGA and the ZW", "Own-risk bearing has no influence on the cover of a wage sanction."], ["Only if the employee himself caused the sanction", "The wage sanction affects the employer, because of its shortcomings in reintegration."]], "1g.4"],
["How are the premium and the benefit of an absenteeism insurance treated for tax purposes for an entrepreneur?", [["The premium is a deductible business expense and the benefit is taxable business income", "The absenteeism insurance covers a business risk; premium and benefit therefore run through the entrepreneur's taxable result."], ["The premium is not deductible and the benefit is untaxed", "That is the treatment of, for example, a housing costs insurance for a private person."], ["The premium is deductible in box 1 as an expense for the entrepreneur's income provision", "That deduction applies to one's own AOV, not to absence of employees."], ["The benefit is taxed as wages of the sick employee", "The benefit goes to the employer; the employee's wages are taxed separately."]], "1i.5"],
["Why do absenteeism insurers often impose requirements on the employer's absence guidance?", [["Good guidance limits the claims burden; without compliance the benefit may be limited", "Insurers attach conditions on occupational health service and Gatekeeper Act compliance to the cover, because quick reintegration shortens absence."], ["Because the AFM prescribes this as a condition for the insurer's licence", "These requirements follow from the insurer's policy conditions, not from an AFM requirement."], ["Because the insurer thereby takes over the role of the UWV", "The UWV remains responsible for the WIA assessment; the insurer does not take that over."], ["Because otherwise the employee has no right to continued payment of wages", "The right to continued payment of wages follows from the law and is separate from the absenteeism insurance."]], "1d.3"],
["Self-employed Koen has an AOV that pays a fixed amount per month as a sum insured policy. He becomes incapacitated for work due to a traffic accident for which someone else is liable. Can the insurer recover the AOV benefit from the liable party?", [["No, with a sum insured policy the right of recourse does not pass to the insurer", "Subrogation applies only to indemnity insurance. With a sum insured policy Koen can recover his own loss from the liable party himself."], ["Yes, the insurer always steps into the rights of the insured", "That applies to indemnity insurance, not to a sum insured policy."], ["Yes, but only after the liable party has itself paid Koen", "The insurer pays out under the policy, regardless of any liability of a third party."], ["No, because an AOV can never be a personal insurance", "An AOV as a sum insured policy is in fact a personal insurance."]], "1f.3"],
["An employer wants to become a WGA own-risk bearer. What applies to the procedure?", [["He applies at least 13 weeks in advance to the Tax Administration, with a guarantee statement", "Own-risk bearing starts on 1 January or 1 July. The application goes to the Tax Administration with a guarantee statement from an insurer or bank."], ["He can switch at any time of the year with immediate effect via the UWV", "Switching is only possible on fixed dates and the application must be made in good time."], ["He needs permission from the AFM for this", "The AFM plays no role in own-risk bearing; a guarantee statement is needed, however."], ["He must have at least a hundred employees and an in-house company doctor", "No minimum number of employees applies to WGA own-risk bearing."]], "1f.9"],
["What is the purpose of the private supplement to the WW and the wage-related WGA (PAWW) agreed in many collective labour agreements?", [["To repair the shortening of the maximum duration of the WW and wage-related WGA", "Through the cao, after the end of the statutory WW or wage-related WGA an employee can receive a supplementary benefit, up to the duration that applied before the shortening."], ["To top up the wage above the maximum daily wage during the WW", "That is the purpose of a private WW supplement insurance; the PAWW repairs the duration, not the level above the maximum daily wage."], ["To give freelancers (zzp'ers) a WW benefit after all if they lack assignments", "The PAWW applies to employees under a participating cao, not to the self-employed."], ["To raise the WW benefit to 100% of the last-earned wage", "The PAWW extends the benefit duration and does not raise the benefit percentage."]], "1g.17"],
["An employer ends its absenteeism insurance and switches to another insurer. An employee is already four months sick at that moment. What is the main point of attention?", [["Whether the current case of sickness is covered via run-off with the old insurer or via run-in with the new insurer", "Without agreements on run-off or run-in, the employer may have to bear the sick employee's wages itself."], ["Nothing, the new insurer always automatically takes over current cases of sickness", "A new insurer often excludes current absence, unless run-in has been expressly insured."], ["The employee must report sick again to the UWV", "A change of absenteeism insurer has no consequences for the sickness report to the UWV."], ["The employer's obligation to continue paying wages lapses on switching", "The obligation to continue paying wages is separate from the insurance and simply remains in place."]], "1g.19"],
["Which combination of factors mainly determines the level of the premium of a private AOV?", [["Occupation, age, insured amount, waiting period and end age", "The occupational risk, age and the chosen cover together determine how large the risk is for the insurer, and thereby the premium."], ["Place of residence, marital status and the number of children", "These personal circumstances are not important premium factors for an AOV."], ["Only the income and the legal form of the business", "Income plays a part through the insured amount, but occupation, age and cover choices are decisive."], ["The insured's assets and the value of his home", "Assets and home value are not usual premium factors for an AOV."]], "1h.4"],
["Why does the unemployment cover of a housing costs insurance often have a period directly after the start in which unemployment is not covered?", [["To prevent someone from insuring while already knowing they will become unemployed", "This period protects the insurer against adverse selection: insuring when the risk is already foreseeable."], ["Because the WW already replaces the full income in that first period", "The WW never replaces the full income; this rule is not for that."], ["Because the premium is tax-deductible in that period", "The premium of a housing costs insurance is not deductible."], ["Because the law prohibits insuring unemployment directly from the policy start date", "There is no statutory prohibition; it is a choice of the insurer."]], "1g.12"],
["An employer offers a collective WGA gap insurance for which employees pay a premium contribution. Employee Daphne does not want to take part and signs a waiver statement (afstandsverklaring). What is the consequence?", [["She has no cover and the employer records that she consciously waives the insurance", "A waiver statement shows that the employee was informed and chose for herself. On incapacity for work she cannot claim the collective cover."], ["She nevertheless remains insured, but pays no premium", "Anyone who waives falls outside the cover; otherwise taking part without a contribution would be possible."], ["The employer must then pay her premium entirely itself", "The waiver statement in fact means there is no premium and no cover for her."], ["On incapacity for work she receives a higher WGA benefit from the UWV", "The UWV's WGA benefit does not change because of waiving a private supplement."]], "1h.9"],
["How are a WW and a WIA benefit treated for tax purposes?", [["As taxable income in box 1; the UWV withholds payroll tax", "UWV benefits are taxed as income; the UWV withholds payroll tax, just like an employer."], ["As untaxed replacement income", "Replacement income from employee insurances is in fact taxed."], ["As income in box 2, because it is a benefit from the government", "Box 2 is for income from a substantial interest, not for benefits."], ["Taxed in box 1, but without withholding; the recipient pays through the tax return", "The UWV does withhold payroll tax on the benefit."]], "1i.5"],
["A self-employed person does not pay the renewal premium of his AOV on time. When may the insurer in principle suspend the cover?", [["Only after a reminder and an unused expiry of a 14-day period", "With an unpaid renewal premium the insurer must first send a reminder; only when the payment period of 14 days expires unused can it suspend the cover. The premium remains due."], ["Directly on the day after the due date, without a reminder", "For a renewal premium the requirement of a reminder with a payment period applies."], ["Only after a year of premium arrears", "The insurer does not have to wait that long; after a reminder and expiry of the period it can suspend."], ["Never, an AOV cannot be suspended for premium arrears", "An AOV can also be suspended in the case of premium arrears after a reminder."]], "1j.1"],
["Which income is most relevant for assessing whether a client can continue to bear his housing costs after incapacity for work?", [["The net disposable income after taxes and premiums", "Fixed costs are paid from what remains net; the adviser therefore compares the net income before and after the risk."], ["The gross annual income including holiday pay", "A gross amount does not say how much is actually available to spend."], ["The test income that the lender used for the mortgage", "The test income determines the maximum mortgage, not what remains after a risk."], ["The taxable income in box 1 from the last tax return", "Taxable income is a tax concept and says little about disposable income."]], "1d.2"],
["Kim (33) is a teacher and earns €3,400 gross per month; her partner Ruben (35) is a self-employed electrician with €45,000 profit per year. They have just bought a house with a mortgage that was only feasible on the basis of their two incomes. Next year they expect their first child. Their adviser makes an income analysis for sickness, incapacity for work, unemployment and death. What is the main point of attention in that analysis?", [["The loss of either of the two incomes can make the housing costs immediately unaffordable", "If the financing rests on two incomes, every risk of each partner is relevant for affordability."], ["Only the risk of the highest earner needs to be analysed", "The loss of the lowest income can also cause problems with tight financing."], ["The risk is small, because two incomes automatically compensate each other if one income falls away", "An income that falls away is not automatically absorbed by the other."], ["Only the pension risk is relevant, because both partners work", "Incapacity for work, unemployment and death remain relevant for two-earner households too."]], "1d.2"],
["Ronald (46) is a self-employed translator and makes €42,000 profit per year. He is married and has two children; his wife has no paid work. The income analysis shows a large income gap on incapacity for work. Ronald finds the AOV premium too high and wants to bear the risk himself. What does the adviser do?", [["Explain the risks and consequences and demonstrably record the client's choice", "The client may choose for himself, but the adviser must show that he made the risk clear and document the choice."], ["Refuse to give advice, because the client does not want to cover the risk with an insurance", "A client may bear a risk himself; refusing is not necessary if the risk has been explained."], ["Take out the AOV anyway, because it is suitable", "Without the client's consent the adviser may not conclude an insurance."], ["Record nothing, because no product was sold", "Precisely a rejection of advice must be recorded in the file."]], "2e.1"],
["In broad terms, how does an employee's income develop in long-term incapacity for work?", [["First continued payment of wages for up to two years, then the WIA with first a wage-related phase", "The income analysis follows these phases: employer, then UWV with wage-related WGA or IVA, and possibly afterwards the WGA follow-up phase."], ["Directly a WIA benefit from the first day of sickness", "In the first two years the employer continues to pay wages; the WIA follows after that."], ["First a year of ZW, then a year of continued payment of wages", "For an employee in service, continued payment of wages by the employer comes first, not the ZW."], ["Two years of continued payment of wages, then always an IVA until the AOW age", "Whether it becomes an IVA or WGA depends on the degree and permanence of the incapacity for work."]], "1i.1"],
["How does an adviser determine the income to be insured of a self-employed person with fluctuating profits?", [["On the basis of an average over several years and the expected development", "An average prevents an exceptionally good or bad year from distorting the advice."], ["On the basis of the highest year, so that in a good year he is never under-insured", "Starting from the best year can lead to over-insurance that the insurer does not accept."], ["On the basis of turnover, because it shows the whole income", "Turnover is not income; the costs must first be deducted."], ["On the basis of the last quarter, because it is the most current", "A quarter is too short to give a reliable picture of the income."]], "1e.1"],
["Where does an adviser find information about an employee's supplementary provisions on incapacity for work or death?", [["In the terms of employment, the cao, the pension rules and the UPO", "Employers often arrange supplements in the cao or pension rules; these sources show what cover the client already has."], ["Only in the payslip of the last month", "A payslip shows deductions, but not the conditions of the schemes."], ["In the Land Registry, where all insurances are registered", "The Land Registry registers real estate, not insurances."], ["With the UWV, which registers all private policies", "The UWV keeps no overview of private or employer insurances."]], "1b.7"],
["Why does an adviser also involve the client's partner in an income analysis?", [["The household bears the costs together and the partner's income influences benefits", "Income risks affect the entire household, and schemes such as the Supplementary Benefits Act and social assistance take partner income into account."], ["Because the partner is legally jointly liable for the premium of an AOV", "There is no statutory liability of the partner for the premium."], ["Because the partner must always be co-insured on every policy", "There is no obligation to co-insure the partner on every policy."], ["Because the WIA benefit depends on the partner's assets", "The WIA has no means test or partner test."]], "1d.2"],
["Bert (41) is a logistics manager and earns €4,600 gross per month. He is married and has two young children; his wife works part-time. At his current employer the survivor's pension is insured on a risk basis. He moves to another employer with a different pension scheme. Which death risk deserves extra attention?", [["His risk-basis survivor's pension may lapse on leaving employment", "A survivor's pension insured on a risk basis is not accrued; after leaving employment (and any short run-off period) it may lapse, while the new scheme may cover less."], ["His Anw entitlement lapses as soon as he joins a new employer with a different pension fund", "The Anw is a national insurance and is separate from the employer."], ["His ORV lapses automatically on changing jobs", "A private ORV is not linked to the employment."], ["His AOW accrual stops temporarily during the transition", "AOW accrual depends on living or working in the Netherlands, not on the employer."]], "1d.2"],
["Case: an employee of adviser Noor loses an unencrypted laptop with client files. Within what period must the firm generally report this data breach to the Dutch Data Protection Authority (Autoriteit Persoonsgegevens)?", [["Within 72 hours of discovery", "The GDPR requires a notification without undue delay and where possible within 72 hours after the breach has been discovered."], ["Within four weeks, after internal investigation", "Four weeks is far too long; the GDPR specifies 72 hours."], ["Within a year, in the annual report", "A notification after the fact in an annual report does not meet the GDPR."], ["Only if the client asks for it himself", "The notification duty applies regardless of a request from the client."]], "1a.6"],
["An employer has had a collective absenteeism insurance for years. Because of a few long-term sick employees, the claims burden has risen sharply in recent years. What may it expect on renewal?", [["The insurer may raise the premium or tighten the conditions", "Collective contracts are often priced on their own claims experience. With a high claims burden, renewal often brings a higher premium or, for example, a longer excess period."], ["The premium falls, because the insurer has already paid out a lot", "A high claims burden in fact leads to a higher premium."], ["Nothing, because the premium of an absenteeism insurance is fixed by law", "There is no statutory premium; the insurer sets the premium itself."], ["The UWV takes over the insurance because of the high absence", "The UWV does not take over private absenteeism insurances."]], "1j.4"],
["Case: an advisory firm stores client files in a cloud package from an external supplier. What must the firm arrange in any case?", [["A processing agreement with the supplier", "An external party that processes personal data for the firm is a processor; the GDPR then requires a processing agreement."], ["Consent from each client for use of that cloud package", "Not consent, but a processing agreement is the required safeguard here."], ["A licence from the AFM for data storage", "The AFM does not grant licences for data storage."], ["A notification to Kifid", "Kifid handles complaints and has no role in data processing."]], "1a.6"],
["Anke and Rob run a catering business together in the form of a general partnership (vennootschap onder firma, vof). What applies to their liability for the debts of the vof?", [["Each partner is liable in full, also privately", "In a vof creditors can hold each partner liable for the whole, also privately. That makes income protection extra important."], ["Only the vof's assets can be claimed, as with a bv", "A vof is not a legal entity; the partners are also privately liable."], ["Each partner is liable for only half of the debts", "Partners are jointly and severally liable, so each for the whole."], ["Only the partner who incurred the debt is liable", "In a vof all partners are liable for the obligations of the vof."]], "1c.1"],
["What form of consent is needed if the processing of health data is based on consent?", [["Explicit consent for that specific purpose", "For special categories of personal data a stricter requirement applies: the consent must be explicit."], ["Tacit consent by accepting the quotation", "Silence or a pre-ticked box is not valid consent, certainly not for health data."], ["Oral consent of the partner", "Consent must come from the data subject themselves, not from someone else."], ["General consent in the general terms and conditions", "A reference in general terms and conditions is not specific and explicit enough."]], "1a.6"],
["Case: during an AOV meeting a client spontaneously tells at length about a recent diagnosis. What is the adviser's correct attitude?", [["Record only what is necessary and point to the health declaration", "Data minimisation means not storing medical details the adviser does not need; the declaration goes directly to the medical adviser."], ["Include the diagnosis in full in the client file, so that it can be used later at the application", "Health data are special; unnecessary recording conflicts with the GDPR."], ["Immediately forward the diagnosis to the insurer by email", "Medical information goes via the health declaration to the medical adviser, not via the adviser."], ["End the conversation, because he may not hear this information", "Hearing it is not prohibited; what matters is handling it carefully."]], "4b.2"],
["What is the role of an insurer's medical adviser in the acceptance of an AOV?", [["He assesses the medical information under professional secrecy and advises the underwriter", "The underwriter receives only the advice, such as an exclusion or surcharge, and no medical details."], ["He goes through the health declaration with the client on behalf of the adviser and supplements it if necessary", "The medical adviser works for the insurer and not on behalf of the adviser."], ["He shares the diagnosis with the adviser so that the adviser can advise better", "Medical details stay with the medical adviser under his professional secrecy."], ["He determines the degree of incapacity for work for the WIA", "That is done by the UWV, not by the medical adviser of a private insurer."]], "1h.2"],
["Case: mortgage adviser Ruud also wants to advise his clients on a private AOV. Which diploma does he in any case need for this besides Wft Basic?", [["Wft Income", "Advice on income insurances such as the AOV falls under the Wft Income module."], ["Wft Non-life Insurance (Personal)", "That module concerns non-life insurances such as contents and liability, not the AOV."], ["Wft Wealth", "Wft Wealth concerns wealth accumulation, not income insurances."], ["Wft Pensions", "Wft Pensions concerns pension schemes, not the private AOV."]], "4b.3"],
["Fleur (36) is a self-employed hairdresser with her own salon and makes €35,000 profit per year. She lives with a partner and has a three-year-old daughter. After a wrist operation she cannot cut hair for months, but the insurer rejects her AOV claim. Fleur disagrees and has already gone through the insurer's internal complaints procedure. Where can she turn then?", [["To Kifid or the civil court", "After the internal complaints procedure, Fleur can submit the dispute with the insurer to Kifid or to the court."], ["To the UWV, which reviews AOV claims", "The UWV reviews public benefits and has no role in private policies."], ["To the AFM, which settles the individual dispute", "The AFM supervises the conduct of financial firms, but does not settle individual disputes."], ["To the Dutch Data Protection Authority", "The Data Protection Authority concerns the protection of personal data, not the assessment of a claim."]], "1a.3"],
["How may an adviser be remunerated for his advice on a private AOV?", [["Directly by the client, because the commission ban applies", "A commission ban applies to the AOV, among others: the adviser may not receive commission from the insurer."], ["With commission from the insurer, provided he discloses it in advance", "Disclosure does not make commission permitted; for the AOV a ban applies."], ["Only with a fixed fee from the insurer per policy", "A fixed fee from the insurer also falls under the commission ban."], ["With a bonus from the insurer for a high premium", "Such an incentive conflicts with the commission ban and with the client's interest."]], "1h.5"],
["Naomi (38) is a pharmacy assistant and earns €1,900 gross per month for three days' work. Her partner dies of cancer and she now cares alone for their six-year-old daughter. She receives a survivor's pension from her partner's pension fund. In addition she applies for an Anw benefit. Is that survivor's pension offset against her Anw benefit?", [["No, a survivor's pension is not income from work and is not offset", "The Anw only offsets income from or in connection with work; a survivor's pension does not fall under that."], ["Yes, the survivor's pension is offset in full against the Anw", "Full offsetting does not take place; the survivor's pension does not count for the Anw."], ["Yes, for 70% as with income from a job", "Partial offsetting applies to employment income, not to a survivor's pension."], ["Only if the pension is higher than the Anw benefit itself", "There is no threshold above which a survivor's pension is offset after all."]], "1i.2"],
["Lotte (34) works as a freelancer (zzp'er) and has been hired as a project leader at a single municipality. She has worked there for three years, four days a week, has a fixed workplace and receives assignments and working hours from her manager. She wants to take out an incapacity for work insurance and asks whether her status as a self-employed person makes any difference to her income risk. Since 1 January 2025 the Tax Administration has been enforcing the assessment of employment relationships again. What is the best advice?", [["Discuss whether her work is actually an employment relationship; that determines which insurances she needs", "With authority, fixed working hours and long-term work for one client there may be an employment relationship; she is then an employee with employee insurances. Since 2025 this is being enforced again."], ["Her status makes no difference, because with a Chamber of Commerce (KvK) registration she is always self-employed", "A KvK registration does not determine the status; what matters is how the work is carried out in practice."], ["She already has a right to a WIA benefit, because she has worked for the same client for more than two years", "A self-employed person is not compulsorily insured for the WIA; only if the work turns out to be an employment relationship is she an employee with employee insurances."], ["The Tax Administration will only enforce against bogus self-employment from 2030, so it is not important now", "The enforcement moratorium was lifted on 1 January 2025; the Tax Administration has been enforcing again since then."]], "1a.8"]
];
